/* Tech 3D · Nivell 1 · unitat 1 «L'espai 3D» · guia del professor (m1-1 … m1-4)
   Material propi de Numi. Classe de 60 minuts; mateix esquema que TGUIDE['r1-1']. Les diapositives «media» mostren
   el model en 3D (TMEDIA.model, tech-model.js): a la pissarra digital es pot girar amb el dit o amb el ratolí. */
Object.assign(TGUIDE, (() => {
  const P = (id, t, s, p, c, o = {}) => ({ id, t, s, p, r: o.r || [0, 0, 0], c, ...o });
  const CASA = [P('base', 'box', [40, 30, 24], [0, 0, 12], '#F5893A'), P('teulada', 'pyr', [46, 36, 18], [0, 0, 33], '#E8453C'), P('porta', 'box', [10, 2, 14], [0, -15.5, 7], '#A0683A'), P('xemeneia', 'cyl', [7, 7, 14], [12, 6, 38], '#9AA3B5')];
  const ROBOT = [P('cos', 'box', [26, 16, 26], [0, 0, 21], '#7C5CFF'), P('cap', 'box', [18, 14, 14], [0, 0, 41], '#5BC0EB'), P('ull1', 'sph', [5, 5, 5], [-4, -7, 43], '#2A2F3A'), P('ull2', 'sph', [5, 5, 5], [4, -7, 43], '#2A2F3A'),
    P('roda1', 'cyl', [12, 12, 6], [-16, 0, 6], '#2A2F3A', { r: [0, 90, 0] }), P('roda2', 'cyl', [12, 12, 6], [16, 0, 6], '#2A2F3A', { r: [0, 90, 0] }), P('antena', 'cyl', [2, 2, 8], [0, 0, 52], '#9AA3B5'), P('bola', 'sph', [5, 5, 5], [0, 0, 57], '#E8453C')];
  const EIXOS = [P('c0', 'box', [10, 10, 10], [0, 0, 5], '#9AA3B5'), P('cx', 'box', [10, 10, 10], [40, 0, 5], '#E5484D'), P('cy', 'box', [10, 10, 10], [0, 40, 5], '#22A06B'), P('cz', 'box', [10, 10, 10], [0, 0, 45], '#2F5BEA')];
  const PUNTS = [P('p1', 'cyl', [14, 14, 14], [-20, 20, 7], '#E8453C'), P('p2', 'cyl', [14, 14, 14], [20, 20, 7], '#3D7BF4'), P('p3', 'cyl', [14, 14, 14], [-20, -20, 7], '#2FB36D'), P('p4', 'cyl', [14, 14, 14], [20, -20, 7], '#F7C531')];
  // m1-2: l'estació de joguina d'en Pau, el fuster (la porta només es veu de davant; la torre rodona, a la dreta)
  const ESTACIO = [P('base', 'box', [50, 24, 18], [0, 0, 9], '#7C5CFF'), P('porta', 'box', [10, 2, 12], [-12, -12.5, 6], '#3A2A6B'), P('torre', 'cyl', [14, 14, 22], [14, 0, 29], '#2FB36D'), P('teula', 'cone', [18, 18, 12], [14, 0, 46], '#EC5FA8')];
  const VA = [P('a', 'box', [30, 30, 10], [0, 0, 5], '#F5893A'), P('b', 'cyl', [16, 16, 20], [0, 0, 20], '#2FB36D')];
  // m1-4: escultures d'exemple
  const ESCULT = [P('peu', 'cyl', [44, 44, 8], [0, 0, 4], '#9AA3B5'), P('columna', 'box', [14, 14, 30], [0, 0, 23], '#7C5CFF'), P('bola', 'sph', [26, 26, 26], [0, 0, 49], '#F7C531'), P('estrella', 'star', [20, 20, 5], [0, 0, 63], '#EC5FA8', { r: [90, 0, 0] })];
  const CONTRAST = [P('base', 'box', [56, 30, 8], [0, 0, 4], '#1B2B6B'), P('con', 'cone', [22, 22, 44], [-14, 0, 30], '#F5893A'), P('bola', 'sph', [24, 24, 24], [14, 0, 19], '#5BC0EB'), P('anell', 'torus', [30, 30, 6], [14, 0, 11], '#EC5FA8')];
  const FLOTA = [P('peu', 'cyl', [40, 40, 8], [0, 0, 4], '#9AA3B5'), P('columna', 'cyl', [14, 14, 30], [0, 0, 23], '#3D7BF4'), P('bola', 'sph', [22, 22, 22], [0, 0, 53], '#F5893A')];
  const ARC = [P('pota1', 'cyl', [20, 20, 20], [-20, 0, 10], '#2FB36D'), P('pota2', 'cyl', [20, 20, 20], [20, 0, 10], '#2FB36D'), P('biga', 'box', [60, 20, 10], [0, 0, 25], '#F7C531')];
  return {
  /* ---------- Sessió 1 · Benvinguts al taller 3D ---------- */
  'm1-1': {
    obj: ["L'alumne/a identifica les tres mides d'un objecte (amplada, fondària i alçada) i les mesura en mil·límetres.|El alumno/a identifica las tres medidas de un objeto (anchura, fondo y altura) y las mide en milímetros.",
      "L'alumne/a gira, apropa i allunya la vista d'un model 3D per observar-lo per tots els costats.|El alumno/a gira, acerca y aleja la vista de un modelo 3D para observarlo por todos los lados.",
      "L'alumne/a reconeix la placa d'impressió i fa servir la quadrícula de 10 mm per estimar mides.|El alumno/a reconoce la placa de impresión y usa la cuadrícula de 10 mm para estimar medidas.",
      "L'alumne/a posa les primeres formes a la placa i les observa des de diferents vistes.|El alumno/a pone las primeras formas en la placa y las observa desde distintas vistas."],
    comp: ["Matemàtiques, sentit espacial: cossos geomètrics, posició i orientació en l'espai|Matemáticas, sentido espacial: cuerpos geométricos, posición y orientación en el espacio",
      "Matemàtiques, sentit de la mesura: el mil·límetre i el centímetre|Matemáticas, sentido de la medida: el milímetro y el centímetro",
      "Tecnologia i digitalització: primer contacte amb el disseny 3D i la fabricació digital|Tecnología y digitalización: primer contacto con el diseño 3D y la fabricación digital",
      "Comunicació: descriure un objecte amb vocabulari espacial precís|Comunicación: describir un objeto con vocabulario espacial preciso"],
    vocab: [['Objecte 3D|Objeto 3D', 'Objecte amb amplada, fondària i alçada: es pot agafar i girar.|Objeto con anchura, fondo y altura: se puede coger y girar.'], ['Amplada|Anchura', "La mida d'esquerra a dreta.|La medida de izquierda a derecha."], ['Fondària|Fondo', 'La mida de davant a darrere.|La medida de delante a detrás.'], ['Alçada|Altura', 'La mida de baix a dalt.|La medida de abajo arriba.'],
      ['Mil·límetre (mm)|Milímetro (mm)', 'La desena part d\'un centímetre: 10 mm = 1 cm.|La décima parte de un centímetro: 10 mm = 1 cm.'], ["Placa d'impressió|Placa de impresión", 'La superfície on la impressora 3D construeix les peces.|La superficie donde la impresora 3D construye las piezas.'], ['Vista|Vista', 'Des d\'on mirem el model: perspectiva, davant, dalt o costat.|Desde dónde miramos el modelo: perspectiva, delante, arriba o lado.']],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Benvinguts al taller 3D»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Bienvenidos al taller 3D»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Regles i capses de diferents mides (de sabates, de llapis, de cereals), una per parella|Reglas y cajas de distintos tamaños (de zapatos, de lápices, de cereales), una por pareja'],
      imprimir: ['Fitxa: mesura la capsa|Ficha: mide la caja'], prep: ['Portar unes quantes capses buides de mides diferents.|Traer unas cuantas cajas vacías de distintos tamaños.', 'Provar abans a l\'ordinador de l\'aula com es gira la vista amb el ratolí i amb la pantalla tàctil.|Probar antes en el ordenador del aula cómo se gira la vista con el ratón y con la pantalla táctil.', 'Si hi ha una impressora 3D al centre, tenir-ne una peça impresa per ensenyar-la.|Si hay una impresora 3D en el centro, tener una pieza impresa para enseñarla.'] },
    plan: [
      { min: 5, t: 'Benvinguts al Taller de Bit|Bienvenidos al Taller de Bit', fase: 'inici', fa: "Presenta el curs: aprendran a dissenyar objectes en 3D que es poden imprimir. Ensenya un objecte imprès (si en teniu) i pregunta com creuen que s'ha fet.|Presenta el curso: aprenderán a diseñar objetos en 3D que se pueden imprimir. Enseña un objeto impreso (si tenéis) y pregunta cómo creen que se ha hecho.",
        diu: ['Què té una capsa que no té un dibuix en un paper?|¿Qué tiene una caja que no tiene un dibujo en un papel?', 'Al final del curs dissenyareu un objecte vostre i el podreu imprimir.|Al final del curso diseñaréis un objeto vuestro y lo podréis imprimir.'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Mirar en 3D|Mirar en 3D', fase: 'teoria', fa: "Explica les tres mides amb una capsa real i després a la pantalla. Ensenya la placa i la quadrícula de 10 mm. Gira el model de la casa a la pissarra digital perquè vegin que el model no es mou: és la càmera la que hi camina al voltant. Acaba amb les quatre vistes.|Explica las tres medidas con una caja real y después en la pantalla. Enseña la placa y la cuadrícula de 10 mm. Gira el modelo de la casa en la pizarra digital para que vean que el modelo no se mueve: es la cámara la que camina a su alrededor. Acaba con las cuatro vistas.",
        diu: ["Si giro la capsa, l'alçada pot passar a ser l'amplada?|Si giro la caja, ¿la altura puede pasar a ser la anchura?", 'Quants quadrets ocupa aquesta peça? Quants mil·límetres són?|¿Cuántos cuadritos ocupa esta pieza? ¿Cuántos milímetros son?'], slides: ['s3', 's4', 's5', 's6'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'Mesura una capsa|Mide una caja', fase: 'desconnectat', fa: "Per parelles, amb una capsa i un regle: identifiquen l'amplada, la fondària i l'alçada, les mesuren i les apunten a la fitxa en mil·límetres. Després giren la capsa i comproven que les mides canvien de nom però no de valor.|Por parejas, con una caja y una regla: identifican la anchura, el fondo y la altura, las miden y las apuntan en la ficha en milímetros. Después giran la caja y comprueban que las medidas cambian de nombre pero no de valor.",
        diu: ['Mesureu de vora a vora, sense comptar el cartró que sobresurt.|Medid de borde a borde, sin contar el cartón que sobresale.', 'Quina mida és la més gran? I si gireu la capsa?|¿Qué medida es la más grande? ¿Y si giráis la caja?'], slides: ['s7'], app: 'Encara no: capses, regles i la fitxa.|Todavía no: cajas, reglas y la ficha.', org: 'Per parelles|Por parejas' },
      { min: 20, t: "A l'ordinador: busca, compta i compara|En el ordenador: busca, cuenta y compara", fase: 'ordinador', fa: "Cada alumne/a fa la sessió a l'app. Passa per les taules quan arribin a l'estrella amagada: és el primer cop que han de girar la vista per resoldre un repte. Als que van ràpid, proposa el repte extra del robot.|Cada alumno/a hace la sesión en la app. Pasa por las mesas cuando lleguen a la estrella escondida: es la primera vez que tienen que girar la vista para resolver un reto. A los que van rápido, proponles el reto extra del robot.",
        diu: ['No toqueu res a l\'atzar: gireu a poc a poc i mireu.|No toquéis nada al azar: girad poco a poco y mirad.', "Des d'on s'hauria de veure? Proveu els botons de les vistes.|¿Desde dónde se tendría que ver? Probad los botones de las vistas."], slides: ['s8', 's9', 's10'], app: "Sessió «Benvinguts al taller 3D», del principi fins a la peça lliure.|Sesión «Bienvenidos al taller 3D», del principio hasta la pieza libre.", org: 'Individual|Individual' },
      { min: 8, t: 'La primera peça|La primera pieza', fase: 'crea', fa: "Deixa que posin formes lliurement a la placa. Demana que mirin la seva peça des de davant, de dalt i del costat i que en triïn la vista preferida. Es desa a «Projectes».|Deja que pongan formas libremente en la placa. Pide que miren su pieza desde delante, desde arriba y desde el lado y que elijan su vista preferida. Se guarda en «Proyectos».",
        diu: ['Quina vista us agrada més del vostre model? Per què?|¿Qué vista os gusta más de vuestro modelo? ¿Por qué?'], slides: ['s11'], app: 'Pas «La teva primera peça».|Paso «Tu primera pieza».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: "Repassa les tres mides i com es gira la vista. Tiquet de sortida oral i proposta per a casa.|Repasa las tres medidas y cómo se gira la vista. Ticket de salida oral y propuesta para casa.",
        diu: ["Digueu-me una cosa de l'aula i les seves tres mides, a ull.|Decidme una cosa del aula y sus tres medidas, a ojo."], slides: ['s12', 's13', 's14'], app: "Les últimes preguntes de la sessió i «Com t'ha anat?».|Las últimas preguntas de la sesión y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Confon la fondària amb l'alçada.|Confunde el fondo con la altura.", "Demana-li que posi la mà a la taula i l'aixequi: això és l'alçada. Després que l'empenyi cap al fons: això és la fondària.|Pídele que ponga la mano en la mesa y la levante: eso es la altura. Después que la empuje hacia el fondo: eso es el fondo."],
      ['Mesura en centímetres i apunta el número com si fossin mil·límetres.|Mide en centímetros y apunta el número como si fueran milímetros.', 'Recorda-li que cada centímetre té 10 rallets petits: 4 cm són 40 mm.|Recuérdale que cada centímetro tiene 10 rayitas pequeñas: 4 cm son 40 mm.'],
      ['Toca les peces en lloc de girar la vista i les mou sense voler.|Toca las piezas en lugar de girar la vista y las mueve sin querer.', "Ensenya-li a arrossegar des d'un lloc buit de la vista (el fons o la placa) i, si cal, a desfer el moviment.|Enséñale a arrastrar desde un sitio vacío de la vista (el fondo o la placa) y, si hace falta, a deshacer el movimiento."],
      ["Es perd: la càmera queda massa a prop o mirant cap a fora.|Se pierde: la cámara queda demasiado cerca o mirando hacia fuera.", 'El botó de centrar la vista (a sota, a l\'esquerra) torna a posar el model al mig.|El botón de centrar la vista (abajo, a la izquierda) vuelve a poner el modelo en el medio.']],
    diff: { mes: "Mesurar dues capses i dir quina és més gran en cada mida. Al taller, posar a la placa una forma de cada tipus i ordenar-les de la més baixa a la més alta.|Medir dos cajas y decir cuál es más grande en cada medida. En el taller, poner en la placa una forma de cada tipo y ordenarlas de la más baja a la más alta.",
      menys: "Fer l'activitat de mesura amb una capsa grossa i marcar amb gomets de colors l'amplada (vermell), la fondària (verd) i l'alçada (blau). A l'app, fer servir els botons de les vistes en lloc d'arrossegar.|Hacer la actividad de medida con una caja grande y marcar con gomets de colores la anchura (rojo), el fondo (verde) y la altura (azul). En la app, usar los botones de las vistas en lugar de arrastrar." },
    aval: { ticket: ['Digues les tres mides d\'un objecte 3D.|Di las tres medidas de un objeto 3D.', 'Com veus el darrere d\'un model al taller?|¿Cómo ves la parte de atrás de un modelo en el taller?'],
      rubric: [['Les tres mides|Las tres medidas', 'Diu i assenyala l\'amplada, la fondària i l\'alçada d\'un objecte.|Dice y señala la anchura, el fondo y la altura de un objeto.', 'Reconeix l\'alçada, però confon l\'amplada i la fondària.|Reconoce la altura, pero confunde la anchura y el fondo.'],
        ['Mesurar en mm|Medir en mm', 'Mesura amb el regle i escriu el resultat en mil·límetres.|Mide con la regla y escribe el resultado en milímetros.', 'Mesura, però barreja centímetres i mil·límetres.|Mide, pero mezcla centímetros y milímetros.'],
        ['Girar la vista|Girar la vista', 'Gira i apropa la vista per trobar el que busca.|Gira y acerca la vista para encontrar lo que busca.', 'Necessita ajuda per orientar-se o mou les peces sense voler.|Necesita ayuda para orientarse o mueve las piezas sin querer.']] },
    casa: "Busqueu a casa tres objectes (una tassa, un llibre, una capsa) i mesureu-ne l'amplada, la fondària i l'alçada en mil·límetres. Quin és el més alt? I el més ample?|Buscad en casa tres objetos (una taza, un libro, una caja) y medid su anchura, fondo y altura en milímetros. ¿Cuál es el más alto? ¿Y el más ancho?",
    intro: "Primera sessió del curs: no es tracta encara de dissenyar, sinó d'aprendre a mirar. L'objectiu és que l'alumnat se senti còmode movent la càmera i que associï les tres mides a paraules precises.|Primera sesión del curso: no se trata aún de diseñar, sino de aprender a mirar. El objetivo es que el alumnado se sienta cómodo moviendo la cámara y que asocie las tres medidas a palabras precisas.",
    claus: ["Les tres mides (amplada, fondària i alçada) depenen de com està girat l'objecte.|Las tres medidas (anchura, fondo y altura) dependen de cómo está girado el objeto.", 'Al taller treballem en mil·límetres, com les impressores 3D.|En el taller trabajamos en milímetros, como las impresoras 3D.', 'Girar la vista no mou el model: canvia des d\'on el mirem.|Girar la vista no mueve el modelo: cambia desde dónde lo miramos.', 'La quadrícula de la placa té quadrets de 10 mm: serveix per estimar mides.|La cuadrícula de la placa tiene cuadritos de 10 mm: sirve para estimar medidas.'],
    prev: ['Saber fer servir el ratolí o la pantalla tàctil (tocar i arrossegar).|Saber usar el ratón o la pantalla táctil (tocar y arrastrar).', 'Saber llegir un regle en centímetres.|Saber leer una regla en centímetros.', 'No cal cap coneixement de disseny 3D.|No hace falta ningún conocimiento de diseño 3D.'],
    faq: [['Què és una impressora 3D?|¿Qué es una impresora 3D?', "Una màquina que fon un fil de plàstic i el diposita capa a capa, de baix a dalt, fins a construir l'objecte. Ho veurem a la unitat 6.|Una máquina que funde un hilo de plástico y lo deposita capa a capa, de abajo arriba, hasta construir el objeto. Lo veremos en la unidad 6."],
      ['Per què mil·límetres i no centímetres?|¿Por qué milímetros y no centímetros?', 'Perquè les peces impreses són petites i han de ser precises: 1 mm de diferència fa que una tapa encaixi o no.|Porque las piezas impresas son pequeñas y tienen que ser precisas: 1 mm de diferencia hace que una tapa encaje o no.'],
      ['Podem imprimir el que fem avui?|¿Podemos imprimir lo que hacemos hoy?', "Es pot, però encara no hem après a fer peces que s'imprimeixin bé. Ho farem més endavant, amb el projecte de la unitat 6.|Se puede, pero aún no hemos aprendido a hacer piezas que se impriman bien. Lo haremos más adelante, con el proyecto de la unidad 6."]],
    tec: [['La vista 3D es veu negra o no es mou.|La vista 3D se ve negra o no se mueve.', "El navegador ha de tenir el 3D (WebGL) activat. Si no, l'app dibuixa una vista més senzilla que també es pot girar. Proveu de tornar a carregar la pàgina.|El navegador tiene que tener el 3D (WebGL) activado. Si no, la app dibuja una vista más sencilla que también se puede girar. Probad a volver a cargar la página."],
      ["En arrossegar, es mou la peça en lloc de la càmera.|Al arrastrar, se mueve la pieza en lugar de la cámara.", "Cal començar a arrossegar fora de les peces. Si s'ha mogut, el botó de desfer (la fletxa) la torna al seu lloc.|Hay que empezar a arrastrar fuera de las piezas. Si se ha movido, el botón de deshacer (la flecha) la vuelve a su sitio."],
      ['Amb un ratolí sense roda no es pot fer zoom.|Con un ratón sin rueda no se puede hacer zoom.', 'El botó de centrar la vista fa que el model ompli la pantalla. A les pantalles tàctils, dos dits.|El botón de centrar la vista hace que el modelo llene la pantalla. En las pantallas táctiles, dos dedos.']],
    extra: ["Fer una «exposició de capses»: totes les capses de la classe ordenades per alçada.|Hacer una «exposición de cajas»: todas las cajas de la clase ordenadas por altura.", 'Buscar a casa o a l\'escola objectes fets amb una impressora 3D.|Buscar en casa o en la escuela objetos hechos con una impresora 3D.', "Descriure un objecte de l'aula només amb les seves mides perquè un company l'endevini.|Describir un objeto del aula solo con sus medidas para que un compañero lo adivine."],
    trans: ['Sessió següent: les vistes de davant, de dalt i del costat, a fons.|Sesión siguiente: las vistas de delante, de arriba y del lado, a fondo.', 'Matemàtiques: la mesura i les unitats de longitud.|Matemáticas: la medida y las unidades de longitud.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Benvinguts al taller 3D|Bienvenidos al taller 3D', x: "Aprenem a mirar objectes en tres dimensions|Aprendemos a mirar objetos en tres dimensiones", nota: "Presenta el Taller de Bit i la Nuvi, la impressora 3D. Explica que avui aprendrem a mirar abans de construir.|Presenta el Taller de Bit y a Nuvi, la impresora 3D. Explica que hoy aprenderemos a mirar antes de construir." },
      { id: 's2', k: 'pregunta', t: "Què té d'especial un objecte 3D?|¿Qué tiene de especial un objeto 3D?", x: 'Una capsa i un dibuix d\'una capsa: en què s\'assemblen i en què són diferents?|Una caja y un dibujo de una caja: ¿en qué se parecen y en qué son diferentes?', nota: "Recull respostes sense corregir. Busquem que diguin que la capsa es pot agafar, girar i que té gruix.|Recoge respuestas sin corregir. Buscamos que digan que la caja se puede coger, girar y que tiene grosor." },
      { id: 's3', k: 'media', t: 'Amplada, fondària i alçada|Anchura, fondo y altura', x: 'Aquesta caixa fa 40 × 30 × 20 mm.|Esta caja mide 40 × 30 × 20 mm.', media: { k: 'model', model: { parts: [P('m', 'box', [40, 30, 20], [0, 0, 10], '#7C5CFF')] } }, nota: "Assenyala cada mida a la pantalla i després en una capsa real. Fes notar que l'ordre és sempre el mateix: amplada, fondària, alçada.|Señala cada medida en la pantalla y después en una caja real. Haz notar que el orden es siempre el mismo: anchura, fondo, altura." },
      { id: 's4', k: 'media', t: "La placa i la quadrícula|La placa y la cuadrícula", x: 'Cada quadret fa 10 mm de costat.|Cada cuadrito mide 10 mm de lado.', media: { k: 'model', model: { parts: [P('a', 'box', [10, 10, 10], [0, 0, 5], '#2FB36D'), P('b', 'box', [20, 10, 10], [30, 20, 5], '#3D7BF4')] }, view: 'top' }, nota: 'Demana que comptin quadrets per dir quant mesura la peça blava (20 mm de llarg i 10 d\'ample).|Pide que cuenten cuadritos para decir cuánto mide la pieza azul (20 mm de largo y 10 de ancho).' },
      { id: 's5', k: 'media', t: 'Girar la vista|Girar la vista', x: 'Un dit gira, dos dits apropen i allunyen.|Un dedo gira, dos dedos acercan y alejan.', media: { k: 'model', model: { parts: CASA } }, nota: "Gira la casa davant de tothom. Pregunta: s'ha mogut la casa o ens hem mogut nosaltres?|Gira la casa delante de todos. Pregunta: ¿se ha movido la casa o nos hemos movido nosotros?" },
      { id: 's6', k: 'anim', t: 'Les vistes|Las vistas', anim: 'm3views', x: 'Perspectiva, davant, dalt i costat.|Perspectiva, delante, arriba y lado.', nota: 'Presenta les vistes com a fotos des de llocs diferents. La sessió següent les treballarem a fons.|Presenta las vistas como fotos desde lugares distintos. En la sesión siguiente las trabajaremos a fondo.' },
      { id: 's7', k: 'activitat', t: 'Mesura una capsa|Mide una caja', timer: 8, punts: ["Digues quina és l'amplada, la fondària i l'alçada.|Di cuál es la anchura, el fondo y la altura.", 'Mesura-les amb el regle i apunta-les en mm.|Mídelas con la regla y apúntalas en mm.', 'Gira la capsa: què canvia?|Gira la caja: ¿qué cambia?'], nota: 'Per parelles. Una persona mesura i l\'altra apunta a la fitxa; després es canvien.|Por parejas. Una persona mide y la otra apunta en la ficha; después se cambian.' },
      { id: 's8', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['Troba l\'estrella amagada.|Encuentra la estrella escondida.', 'Compta les peces de la torre.|Cuenta las piezas de la torre.', 'Toca la peça més alta.|Toca la pieza más alta.'], nota: "Obriu la sessió a l'app. Recorda que cal girar la vista per trobar el que no es veu.|Abrid la sesión en la app. Recuerda que hay que girar la vista para encontrar lo que no se ve." },
      { id: 's9', k: 'media', t: 'Quantes peces té?|¿Cuántas piezas tiene?', x: "Algunes peces no es veuen des de davant.|Algunas piezas no se ven desde delante.", media: { k: 'model', model: { parts: ROBOT }, view: 'front' }, nota: 'Fes-ho junts per als que no han arribat al repte: comptem a la vista de davant i després girem.|Hacedlo juntos para quienes no han llegado al reto: contamos en la vista de delante y después giramos.' },
      { id: 's10', k: 'concepte', t: 'La Nuvi construeix capa a capa|Nuvi construye capa a capa', x: "La impressora fa l'objecte de baix a dalt, en capes primes com un full. Per això, al taller, les peces han de tocar la placa.|La impresora hace el objeto de abajo arriba, en capas finas como una hoja. Por eso, en el taller, las piezas tienen que tocar la placa.", nota: 'Primera idea de fabricació: ho anirem recuperant. Si teniu una peça impresa, ensenyeu-ne les capes de prop.|Primera idea de fabricación: la iremos recuperando. Si tenéis una pieza impresa, enseñad sus capas de cerca.' },
      { id: 's11', k: 'repte', t: 'La teva primera peça|Tu primera pieza', punts: ['Posa almenys 2 formes a la placa.|Pon al menos 2 formas en la placa.', 'Mira-la de davant, de dalt i del costat.|Mírala desde delante, desde arriba y desde el lado.', 'Desa-la a «Projectes».|Guárdala en «Proyectos».'], nota: "Activitat lliure: el que importa és que facin servir les vistes. Pregunta'ls quina vista els agrada més.|Actividad libre: lo que importa es que usen las vistas. Pregúntales qué vista les gusta más." },
      { id: 's12', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["Un objecte 3D té amplada, fondària i alçada.|Un objeto 3D tiene anchura, fondo y altura.", 'Al taller mesurem en mil·límetres.|En el taller medimos en milímetros.', 'Girem la vista per veure el model per tots els costats.|Giramos la vista para ver el modelo por todos los lados.'], nota: 'Llegiu-ho junts en veu alta.|Leedlo juntos en voz alta.' },
      { id: 's13', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ["Digues les tres mides d'un objecte 3D.|Di las tres medidas de un objeto 3D.", "Com veus el darrere d'un model?|¿Cómo ves la parte de atrás de un modelo?"], nota: 'Oral, abans de sortir: cada alumne/a respon una pregunta.|Oral, antes de salir: cada alumno/a responde una pregunta.' },
      { id: 's14', k: 'concepte', t: 'A casa|En casa', x: "Mesura tres objectes de casa en mil·límetres. Quin és el més alt? I el més ample?|Mide tres objetos de casa en milímetros. ¿Cuál es el más alto? ¿Y el más ancho?", nota: 'Proposta opcional. La sessió següent podeu començar comparant les mesures.|Propuesta opcional. En la sesión siguiente podéis empezar comparando las medidas.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa: mesura la capsa|Ficha: mide la caja', k: 'fitxa', intro: 'Mesura la capsa amb un regle i escriu les mides en mil·límetres.|Mide la caja con una regla y escribe las medidas en milímetros.',
      items: [{ q: "Amplada (d'esquerra a dreta): ____ mm|Anchura (de izquierda a derecha): ____ mm", sol: 'Depèn de la capsa (per exemple, 180 mm).|Depende de la caja (por ejemplo, 180 mm).' }, { q: 'Fondària (de davant a darrere): ____ mm|Fondo (de delante a detrás): ____ mm', sol: 'Depèn de la capsa (per exemple, 110 mm).|Depende de la caja (por ejemplo, 110 mm).' },
        { q: 'Alçada (de baix a dalt): ____ mm|Altura (de abajo arriba): ____ mm', sol: 'Depèn de la capsa (per exemple, 90 mm).|Depende de la caja (por ejemplo, 90 mm).' }, { q: 'Gira la capsa. Quina mida ha passat a ser l\'alçada?|Gira la caja. ¿Qué medida ha pasado a ser la altura?', sol: 'La que ara va de baix a dalt: el valor és el mateix, però el nom canvia.|La que ahora va de abajo arriba: el valor es el mismo, pero el nombre cambia.' }] }]
  },
  /* ---------- Sessió 2 · Davant, dalt i costat ---------- */
  'm1-2': {
    obj: ["L'alumne/a reconeix les tres vistes d'un objecte (davant o alçat, dalt o planta i costat o perfil) i les anomena.|El alumno/a reconoce las tres vistas de un objeto (delante o alzado, arriba o planta y lado o perfil) y las nombra.",
      "L'alumne/a explica quines dues mides mostra cada vista i quina amaga.|El alumno/a explica qué dos medidas muestra cada vista y cuál esconde.",
      "L'alumne/a relaciona una vista plana amb el model 3D que li correspon i descobreix que una sola vista pot enganyar.|El alumno/a relaciona una vista plana con el modelo 3D que le corresponde y descubre que una sola vista puede engañar.",
      "L'alumne/a fa servir la vista de dalt per col·locar peces a la placa amb precisió.|El alumno/a usa la vista de arriba para colocar piezas en la placa con precisión."],
    comp: ["Matemàtiques, sentit espacial: representació plana de cossos (vistes) i visualització|Matemáticas, sentido espacial: representación plana de cuerpos (vistas) y visualización",
      "Matemàtiques, raonament: comparar representacions i justificar quina correspon a un objecte|Matemáticas, razonamiento: comparar representaciones y justificar cuál corresponde a un objeto",
      "Tecnologia i digitalització: interpretar croquis i plànols senzills|Tecnología y digitalización: interpretar croquis y planos sencillos",
      "Comunicació: descriure un objecte amb el vocabulari de les vistes|Comunicación: describir un objeto con el vocabulario de las vistas"],
    vocab: [['Vista|Vista', "El dibuix pla del que veiem des d'un lloc fix.|El dibujo plano de lo que vemos desde un sitio fijo."], ['Alçat|Alzado', 'La vista de davant: mostra l\'amplada i l\'alçada.|La vista de delante: muestra la anchura y la altura.'],
      ['Planta|Planta', "La vista de dalt: mostra l'amplada i la fondària.|La vista de arriba: muestra la anchura y el fondo."], ['Perfil|Perfil', 'La vista del costat: mostra la fondària i l\'alçada.|La vista del lado: muestra el fondo y la altura.'],
      ['Silueta|Silueta', "La forma del contorn d'un objecte, sense detalls.|La forma del contorno de un objeto, sin detalles."], ['Plànol|Plano', "Dibuix tècnic d'un objecte o d'un edifici fet amb vistes i mides.|Dibujo técnico de un objeto o de un edificio hecho con vistas y medidas."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Davant, dalt i costat»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Delante, arriba y lado»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión',
      'Per parella: 6-8 blocs de construcció (cubs encaixables, peces de fusta o de construcció) i un llibre gran per amagar la figura|Por pareja: 6-8 bloques de construcción (cubos encajables, piezas de madera o de construcción) y un libro grande para esconder la figura', 'Una tassa o un got per a la pregunta inicial|Una taza o un vaso para la pregunta inicial'],
      imprimir: ['Fitxa: les tres vistes|Ficha: las tres vistas', 'Quadrícula per dibuixar vistes (una per parella)|Cuadrícula para dibujar vistas (una por pareja)'],
      prep: ["Preparar una bossa per parella amb els blocs i comprovar que n'hi ha prou per fer figures de 2 pisos.|Preparar una bolsa por pareja con los bloques y comprobar que hay suficientes para hacer figuras de 2 pisos.", "Provar a l'ordinador de l'aula els botons de vista (perspectiva, davant, dalt i costat).|Probar en el ordenador del aula los botones de vista (perspectiva, delante, arriba y lado).",
        "Tenir a mà una tassa per ensenyar-la des de dalt (es veu un cercle amb una nansa).|Tener a mano una taza para enseñarla desde arriba (se ve un círculo con un asa)."] },
    plan: [
      { min: 5, t: 'Què és això?|¿Qué es esto?', fase: 'inici', fa: "Aguanta una tassa per sobre dels ulls de l'alumnat i deixa que la vegin només des de sota, o descriu-la des de dalt: «Veig un cercle amb un ganxo al costat». Que endevinin què és. Presenta l'encàrrec d'en Pau, el fuster: tres dibuixos en lloc d'una foto.|Sostén una taza por encima de los ojos del alumnado y deja que la vean solo desde abajo, o descríbela desde arriba: «Veo un círculo con un gancho al lado». Que adivinen qué es. Presenta el encargo de Pau, el carpintero: tres dibujos en lugar de una foto.",
        diu: ['Si només veieu el cercle, podria ser una pilota? I un got?|Si solo veis el círculo, ¿podría ser una pelota? ¿Y un vaso?', "Per què creieu que en Pau ens envia tres dibuixos i no un?|¿Por qué creéis que Pau nos envía tres dibujos y no uno?"], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 13, t: 'Les tres vistes|Las tres vistas', fase: 'teoria', fa: "Presenta les tres vistes amb l'animació dels ulls i, després, amb l'estació en 3D a la pissarra digital: prem els botons de davant, de dalt i del costat i demana què es veu i què no. Treballa la idea clau: cada vista mostra dues mides i n'amaga una. Acaba amb el cub i el cilindre bessons.|Presenta las tres vistas con la animación de los ojos y, después, con la estación en 3D en la pizarra digital: pulsa los botones de delante, de arriba y del lado y pregunta qué se ve y qué no. Trabaja la idea clave: cada vista muestra dos medidas y esconde una. Acaba con el cubo y el cilindro gemelos.",
        diu: ['Des de dalt, sabem si la torre és alta o baixa?|Desde arriba, ¿sabemos si la torre es alta o baja?', 'Quina vista us diu on és la porta?|¿Qué vista os dice dónde está la puerta?', 'Aquests dos quadrats són iguals… o no?|Estos dos cuadrados son iguales… ¿o no?'], slides: ['s3', 's4', 's5', 's6', 's7', 's8'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'Fotògrafs de blocs|Fotógrafos de bloques', fase: 'desconnectat', fa: "Per parelles, una persona construeix una figura amagada darrere del llibre i en dibuixa les tres vistes a la quadrícula. L'altra la reconstrueix només amb els dibuixos. Després es canvien. Al final, pregunta quina vista els ha estat més útil.|Por parejas, una persona construye una figura escondida detrás del libro y dibuja sus tres vistas en la cuadrícula. La otra la reconstruye solo con los dibujos. Después se cambian. Al final, pregunta qué vista les ha sido más útil.",
        diu: ["Dibuixeu cada bloc com un quadret: res de perspectiva, com si l'aixaféssiu contra un vidre.|Dibujad cada bloque como un cuadrito: nada de perspectiva, como si lo aplastarais contra un cristal.", 'Amb un sol dibuix, ho hauríeu encertat?|Con un solo dibujo, ¿lo habríais acertado?'], slides: ['s9'], app: 'Encara no: blocs, llibre i quadrícula.|Todavía no: bloques, libro y cuadrícula.', org: 'Per parelles|Por parejas' },
      { min: 20, t: "A l'ordinador: llegir i fer servir les vistes|En el ordenador: leer y usar las vistas", fase: 'ordinador', fa: "Fan la sessió a l'app: reconèixer vistes, trobar el cilindre amagat, relacionar una vista de dalt amb el seu model i col·locar peces fent servir la vista de dalt. Passa per les taules als reptes de col·locar: comprova que canvien a la vista de dalt abans d'arrossegar.|Hacen la sesión en la app: reconocer vistas, encontrar el cilindro escondido, relacionar una vista de arriba con su modelo y colocar piezas usando la vista de arriba. Pasa por las mesas en los retos de colocar: comprueba que cambian a la vista de arriba antes de arrastrar.",
        diu: ['Quin botó et posa la vista de dalt?|¿Qué botón te pone la vista de arriba?', 'Mira el fantasma des de dalt: ara és un cercle o un quadrat?|Mira el fantasma desde arriba: ¿ahora es un círculo o un cuadrado?'], slides: ['s10', 's11', 's12'], app: 'Sessió «Davant, dalt i costat», fins a «Una figura per a en Pau».|Sesión «Delante, arriba y lado», hasta «Una figura para Pau».', org: 'Individual|Individual' },
      { min: 7, t: 'Una figura per a en Pau|Una figura para Pau', fase: 'crea', fa: "Cada alumne/a fa una figura de 3 peces o més i la mira amb els tres botons. Demana que triïn la vista preferida i que la diguin al company del costat. Es desa al portafoli.|Cada alumno/a hace una figura de 3 piezas o más y la mira con los tres botones. Pide que elijan la vista preferida y que se la digan al compañero de al lado. Se guarda en el portafolio.",
        diu: ['Quina vista sorprendria més en Pau? Per què?|¿Qué vista sorprendería más a Pau? ¿Por qué?'], slides: ['s13'], app: 'Pas «Una figura per a en Pau».|Paso «Una figura para Pau».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: 'Repassa els tres noms (alçat, planta i perfil) i quina mida amaga cada vista. Tiquet de sortida amb els dits: un dit per a davant, dos per a dalt i tres per al costat.|Repasa los tres nombres (alzado, planta y perfil) y qué medida esconde cada vista. Ticket de salida con los dedos: un dedo para delante, dos para arriba y tres para el lado.',
        diu: ["Us dic una mida i em dieu en quina vista no es veu: l'alçada!|Os digo una medida y me decís en qué vista no se ve: ¡la altura!"], slides: ['s14', 's15', 's16'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [['Confon la vista del costat amb la de davant.|Confunde la vista del lado con la de delante.', "Ajuda'l a buscar un detall que només es veu de cara, com la porta de l'estació. Si no hi és, és el costat.|Ayúdale a buscar un detalle que solo se ve de cara, como la puerta de la estación. Si no está, es el lado."],
      ["Creu que la vista de dalt també mostra l'alçada.|Cree que la vista de arriba también muestra la altura.", "Posa dos objectes d'alçades diferents a la taula i que els miri des de dalt amb un ull tancat: semblen igual d'alts?|Pon dos objetos de alturas distintas en la mesa y que los mire desde arriba con un ojo cerrado: ¿parecen igual de altos?"],
      ['Dibuixa la figura en perspectiva en lloc de fer una vista plana.|Dibuja la figura en perspectiva en lugar de hacer una vista plana.', "Digues-li que imagini que aixafa la figura contra el vidre d'una finestra: només queda el contorn i cada bloc és un quadret.|Dile que imagine que aplasta la figura contra el cristal de una ventana: solo queda el contorno y cada bloque es un cuadrito."],
      ['Arrossega la peça però no la deixa dins del fantasma.|Arrastra la pieza pero no la deja dentro del fantasma.', 'Que posi la vista de dalt: el fantasma es veu com una forma transparent i la quadrícula ajuda. En aquests reptes la peça salta de 10 en 10 mm.|Que ponga la vista de arriba: el fantasma se ve como una forma transparente y la cuadrícula ayuda. En estos retos la pieza salta de 10 en 10 mm.']],
    diff: { mes: "Dibuixar les tres vistes d'un objecte de l'aula (una cadira, una motxilla) i que un company endevini què és. A l'app, fer la figura lliure de manera que des de davant sembli una cosa i des de dalt una altra.|Dibujar las tres vistas de un objeto del aula (una silla, una mochila) y que un compañero adivine qué es. En la app, hacer la figura libre de manera que desde delante parezca una cosa y desde arriba otra.",
      menys: "A l'activitat sense pantalla, fer figures d'un sol pis (3-4 blocs) i dibuixar només la vista de dalt. A l'app, fer servir sempre els botons de vista en lloc de girar amb el dit.|En la actividad sin pantalla, hacer figuras de un solo piso (3-4 bloques) y dibujar solo la vista de arriba. En la app, usar siempre los botones de vista en lugar de girar con el dedo." },
    aval: { ticket: ['Com es diu la vista de dalt?|¿Cómo se llama la vista de arriba?', 'Quina mida no es veu des de davant?|¿Qué medida no se ve desde delante?'],
      rubric: [['Les tres vistes|Las tres vistas', 'Anomena i reconeix les tres vistes en un model.|Nombra y reconoce las tres vistas en un modelo.', 'Reconeix la de dalt, però confon la de davant i la del costat.|Reconoce la de arriba, pero confunde la de delante y la del lado.'],
        ['Mides de cada vista|Medidas de cada vista', 'Diu quines dues mides mostra cada vista i quina amaga.|Dice qué dos medidas muestra cada vista y cuál esconde.', "Sap que les vistes són planes, però no relaciona cada una amb les seves mides.|Sabe que las vistas son planas, pero no relaciona cada una con sus medidas."],
        ['Fer servir les vistes|Usar las vistas', 'Canvia de vista per resoldre un repte (trobar o col·locar una peça).|Cambia de vista para resolver un reto (encontrar o colocar una pieza).', 'Necessita que li recordin que pot canviar de vista.|Necesita que le recuerden que puede cambiar de vista.']] },
    casa: "Tria un objecte de casa (una tassa, una joguina, un tetrabric) i dibuixa'n la vista de davant, la de dalt i la del costat. Ensenya només un dibuix a algú de la família: endevina què és? I amb els tres?|Elige un objeto de casa (una taza, un juguete, un brik) y dibuja su vista de delante, la de arriba y la del lado. Enseña solo un dibujo a alguien de la familia: ¿adivina qué es? ¿Y con los tres?",
    intro: "Sessió de visualització espacial: passem de mirar el model girant la càmera a pensar-lo en dibuixos plans. És una habilitat que costa al principi i que es treballa molt millor amb objectes de veritat a les mans: l'activitat dels blocs és el cor de la sessió.|Sesión de visualización espacial: pasamos de mirar el modelo girando la cámara a pensarlo en dibujos planos. Es una habilidad que cuesta al principio y que se trabaja mucho mejor con objetos de verdad en las manos: la actividad de los bloques es el corazón de la sesión.",
    claus: ['Una vista és un dibuix pla des d\'un lloc fix: davant (alçat), dalt (planta) i costat (perfil).|Una vista es un dibujo plano desde un sitio fijo: delante (alzado), arriba (planta) y lado (perfil).', 'Cada vista mostra dues mides i n\'amaga una.|Cada vista muestra dos medidas y esconde una.',
      'Objectes diferents poden tenir la mateixa vista: per això en calen almenys dues.|Objetos distintos pueden tener la misma vista: por eso hacen falta al menos dos.', 'La vista de dalt és la millor per col·locar peces a la placa.|La vista de arriba es la mejor para colocar piezas en la placa.'],
    prev: ['Haver fet la sessió «Benvinguts al taller 3D» (girar la vista i els botons).|Haber hecho la sesión «Bienvenidos al taller 3D» (girar la vista y los botones).', "Conèixer les paraules amplada, fondària i alçada.|Conocer las palabras anchura, fondo y altura.", 'Saber arrossegar amb el ratolí o amb el dit.|Saber arrastrar con el ratón o con el dedo.'],
    faq: [['Per què es diuen alçat, planta i perfil?|¿Por qué se llaman alzado, planta y perfil?', "Són els noms que fan servir els arquitectes i els enginyers als plànols. L'alçat mostra com s'aixeca l'objecte, la planta és com el veu el terra des de dalt i el perfil és el contorn de costat.|Son los nombres que usan los arquitectos y los ingenieros en los planos. El alzado muestra cómo se levanta el objeto, la planta es cómo lo ve el suelo desde arriba y el perfil es el contorno de lado."],
      ['La vista de perspectiva també és una vista?|¿La vista de perspectiva también es una vista?', 'Sí, però no és plana: s\'hi veuen tres cares alhora i les mides queden deformades. Serveix per mirar; les vistes planes serveixen per mesurar.|Sí, pero no es plana: se ven tres caras a la vez y las medidas quedan deformadas. Sirve para mirar; las vistas planas sirven para medir.'],
      ["I la vista de darrere o de sota?|¿Y la vista de detrás o de abajo?", 'També existeixen. Normalment amb tres vistes n\'hi ha prou, però si un objecte té detalls al darrere es dibuixa també aquella vista.|También existen. Normalmente con tres vistas basta, pero si un objeto tiene detalles detrás se dibuja también esa vista.']],
    tec: [["En prémer un botó de vista, el model sembla molt petit o tallat.|Al pulsar un botón de vista, el modelo parece muy pequeño o cortado.", 'El botó de centrar la vista (a sota, a l\'esquerra) torna a ajustar el model a la pantalla.|El botón de centrar la vista (abajo, a la izquierda) vuelve a ajustar el modelo a la pantalla.'],
      ['Als reptes de col·locar, la peça no es mou fins on vol.|En los retos de colocar, la pieza no se mueve hasta donde quiere.', "La peça salta de 10 en 10 mm: cal deixar-la anar quan coincideix amb el fantasma. També es pot fer servir la pestanya Posició.|La pieza salta de 10 en 10 mm: hay que soltarla cuando coincide con el fantasma. También se puede usar la pestaña Posición."],
      ['A les preguntes amb imatges, les miniatures triguen a sortir.|En las preguntas con imágenes, las miniaturas tardan en salir.', "L'app dibuixa cada miniatura en 3D: en ordinadors lents pot trigar uns segons. Cal esperar abans de triar.|La app dibuja cada miniatura en 3D: en ordenadores lentos puede tardar unos segundos. Hay que esperar antes de elegir."]],
    extra: ["Buscar plànols de veritat (el de l'escola, el d'un pis en un fulletó) i descobrir que són vistes de dalt.|Buscar planos de verdad (el de la escuela, el de un piso en un folleto) y descubrir que son vistas de arriba.", "Fer un «museu d'ombres»: amb una llanterna, projectar la silueta d'objectes a la paret i endevinar-los.|Hacer un «museo de sombras»: con una linterna, proyectar la silueta de objetos en la pared y adivinarlos.", "Inventar un objecte que de davant sembli un quadrat, de dalt un cercle i del costat un triangle.|Inventar un objeto que de delante parezca un cuadrado, de arriba un círculo y del lado un triángulo."],
    trans: ['Sessió següent: els eixos x, y, z i les coordenades.|Sesión siguiente: los ejes x, y, z y las coordenadas.', 'Matemàtiques: cossos geomètrics i les seves representacions planes.|Matemáticas: cuerpos geométricos y sus representaciones planas.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Davant, dalt i costat|Delante, arriba y lado', x: 'Tres dibuixos per entendre un objecte 3D|Tres dibujos para entender un objeto 3D', nota: "Presenta l'encàrrec d'en Pau, el fuster: una estació de tren explicada amb tres dibuixos.|Presenta el encargo de Pau, el carpintero: una estación de tren explicada con tres dibujos." },
      { id: 's2', k: 'pregunta', t: 'Què és això?|¿Qué es esto?', x: 'Des de dalt es veu un cercle amb un ganxo al costat.|Desde arriba se ve un círculo con un gancho al lado.', nota: 'És una tassa vista des de dalt. Ensenya-la de debò i gira-la per mostrar que des de davant es veu diferent.|Es una taza vista desde arriba. Enséñala de verdad y gírala para mostrar que desde delante se ve distinta.' },
      { id: 's3', k: 'anim', t: 'Tres llocs per mirar|Tres sitios para mirar', anim: 'm12cams', x: 'Davant (alçat), dalt (planta) i costat (perfil).|Delante (alzado), arriba (planta) y lado (perfil).', nota: "Assenyala cada ull i la «foto» que fa. Repetiu junts els tres noms.|Señala cada ojo y la «foto» que hace. Repetid juntos los tres nombres." },
      { id: 's4', k: 'media', t: "L'alçat: la vista de davant|El alzado: la vista de delante", x: "Veiem l'amplada i l'alçada, i la porta.|Vemos la anchura y la altura, y la puerta.", media: { k: 'model', model: { parts: ESTACIO }, view: 'front', spin: false }, nota: "Pregunta: sabem si l'estació és prima o gruixuda? (No: la fondària no es veu.)|Pregunta: ¿sabemos si la estación es delgada o gruesa? (No: el fondo no se ve.)" },
      { id: 's5', k: 'media', t: 'La planta: la vista de dalt|La planta: la vista de arriba', x: "Veiem l'amplada i la fondària. La torre és un cercle.|Vemos la anchura y el fondo. La torre es un círculo.", media: { k: 'model', model: { parts: ESTACIO }, view: 'top', spin: false }, nota: "Fes notar que el con i el cilindre es confonen en un sol cercle: des de dalt no se'n veu l'alçada.|Haz notar que el cono y el cilindro se confunden en un solo círculo: desde arriba no se ve su altura." },
      { id: 's6', k: 'media', t: 'El perfil: la vista del costat|El perfil: la vista del lado', x: 'Veiem la fondària i l\'alçada. La porta no hi surt.|Vemos el fondo y la altura. La puerta no sale.', media: { k: 'model', model: { parts: ESTACIO }, view: 'right', spin: false }, nota: "Compara-la amb l'alçat: l'estació sembla més estreta i la torre queda al mig.|Compárala con el alzado: la estación parece más estrecha y la torre queda en el medio." },
      { id: 's7', k: 'anim', t: 'Cada vista amaga una mida|Cada vista esconde una medida', anim: 'm12dims', x: 'Amplada (x), fondària (y) i alçada (z): cada vista en mostra dues.|Anchura (x), fondo (y) y altura (z): cada vista muestra dos.', nota: "Lligueu els colors amb els eixos de la sessió següent: vermell x, verd y i blau z.|Relacionad los colores con los ejes de la sesión siguiente: rojo x, verde y y azul z." },
      { id: 's8', k: 'anim', t: 'Una sola vista pot enganyar|Una sola vista puede engañar', anim: 'm12trick', x: 'De davant són iguals; de dalt, no.|De delante son iguales; de arriba, no.', nota: 'Demana altres parelles d\'objectes que es confonguin en una vista (una pilota i un disc, des de dalt).|Pide otras parejas de objetos que se confundan en una vista (una pelota y un disco, desde arriba).' },
      { id: 's9', k: 'activitat', t: 'Fotògrafs de blocs|Fotógrafos de bloques', timer: 10, punts: ['Construeix una figura amagada darrere del llibre.|Construye una figura escondida detrás del libro.', 'Dibuixa-la de davant, de dalt i del costat.|Dibújala de delante, de arriba y del lado.', 'El company la reconstrueix només amb els dibuixos.|El compañero la reconstruye solo con los dibujos.'], nota: 'A la meitat del temps, canvien els papers.|A mitad del tiempo, cambian los papeles.' },
      { id: 's10', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['Quina vista és?|¿Qué vista es?', 'Troba el cilindre bessó.|Encuentra el cilindro gemelo.', 'Col·loca les peces amb la vista de dalt.|Coloca las piezas con la vista de arriba.'], nota: "Obriu la sessió a l'app. Recorda els quatre botons de vista de dalt de la pantalla 3D.|Abrid la sesión en la app. Recuerda los cuatro botones de vista de arriba de la pantalla 3D." },
      { id: 's11', k: 'media', t: 'De quin model és aquesta planta?|¿De qué modelo es esta planta?', x: 'Un quadrat amb un cercle al mig.|Un cuadrado con un círculo en el medio.', media: { k: 'model', model: { parts: VA }, view: 'top', spin: false }, nota: 'Fes-ho junts si costa: girem el model i comprovem que la peça de dalt és un cilindre.|Hacedlo juntos si cuesta: giramos el modelo y comprobamos que la pieza de arriba es un cilindro.' },
      { id: 's12', k: 'concepte', t: 'La vista de dalt per col·locar|La vista de arriba para colocar', x: 'Des de dalt, el fantasma és una forma transparent a la quadrícula: arrossega la peça fins que coincideixin.|Desde arriba, el fantasma es una forma transparente en la cuadrícula: arrastra la pieza hasta que coincidan.', nota: 'Els arquitectes col·loquen els mobles en el plànol, que és una vista de dalt.|Los arquitectos colocan los muebles en el plano, que es una vista de arriba.' },
      { id: 's13', k: 'repte', t: 'Una figura per a en Pau|Una figura para Pau', punts: ['Almenys 3 peces a la placa.|Al menos 3 piezas en la placa.', 'Que es vegi diferent de cada vista.|Que se vea distinta desde cada vista.', 'Tria la teva vista preferida.|Elige tu vista preferida.'], nota: "Quan acabin, demana que ensenyin la vista preferida al company i expliquin per què.|Cuando terminen, pide que enseñen la vista preferida al compañero y expliquen por qué." },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Alçat (davant), planta (dalt) i perfil (costat).|Alzado (delante), planta (arriba) y perfil (lado).', 'Cada vista mostra dues mides i n\'amaga una.|Cada vista muestra dos medidas y esconde una.', 'Una sola vista pot enganyar: en calen almenys dues.|Una sola vista puede engañar: hacen falta al menos dos.'], nota: 'Llegiu-ho junts en veu alta.|Leedlo juntos en voz alta.' },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Com es diu la vista de dalt?|¿Cómo se llama la vista de arriba?', 'Quina mida no es veu des de davant?|¿Qué medida no se ve desde delante?'], nota: "Amb els dits: un dit si és la de davant, dos si és la de dalt, tres si és la del costat.|Con los dedos: un dedo si es la de delante, dos si es la de arriba, tres si es la del lado." },
      { id: 's16', k: 'concepte', t: 'A casa|En casa', x: "Dibuixa un objecte de casa des de davant, de dalt i del costat. Algú l'endevina amb un sol dibuix?|Dibuja un objeto de casa desde delante, desde arriba y desde el lado. ¿Alguien lo adivina con un solo dibujo?", nota: 'Proposta opcional. La sessió següent podeu començar endevinant alguns dibuixos.|Propuesta opcional. En la sesión siguiente podéis empezar adivinando algunos dibujos.' }
    ],
    print: [
      { id: 'p1', t: 'Fitxa: les tres vistes|Ficha: las tres vistas', k: 'fitxa', intro: "Respon les preguntes pensant en l'estació d'en Pau: una caixa amb una porta al davant i una torre rodona amb teulada a la dreta.|Responde las preguntas pensando en la estación de Pau: una caja con una puerta delante y una torre redonda con tejado a la derecha.",
        items: [{ q: "En quina vista es veu la porta de l'estació?|¿En qué vista se ve la puerta de la estación?", sol: "A la de davant (alçat).|En la de delante (alzado)." },
          { q: 'Com es veu la torre rodona des de dalt?|¿Cómo se ve la torre redonda desde arriba?', sol: 'Com un cercle.|Como un círculo.' },
          { q: "Quines dues mides es veuen a la vista del costat?|¿Qué dos medidas se ven en la vista del lado?", sol: "La fondària i l'alçada.|El fondo y la altura." },
          { q: 'Dibuixa un objecte que de davant sigui un quadrat i de dalt un cercle.|Dibuja un objeto que de delante sea un cuadrado y de arriba un círculo.', sol: "Un cilindre tan alt com ample (una llauna baixa, per exemple).|Un cilindro tan alto como ancho (una lata baja, por ejemplo).", big: true }] },
      { id: 'p2', t: 'Quadrícula per dibuixar vistes|Cuadrícula para dibujar vistas', k: 'graella', w: 12, h: 8, intro: "Dibuixa la teva figura de blocs: cada bloc és un quadret. Fes la vista de davant a l'esquerra i la de dalt a la dreta; la del costat, a sota.|Dibuja tu figura de bloques: cada bloque es un cuadrito. Haz la vista de delante a la izquierda y la de arriba a la derecha; la del lado, debajo.",
        legend: [['⬛', 'Un bloc = un quadret|Un bloque = un cuadrito'], ['1', 'Vista de davant (alçat)|Vista de delante (alzado)'], ['2', 'Vista de dalt (planta)|Vista de arriba (planta)'], ['3', 'Vista del costat (perfil)|Vista del lado (perfil)']],
        items: [{ q: 'Vista del costat (perfil):|Vista del lado (perfil):', big: true }, { q: 'El meu company ha encertat la figura? Quina vista li ha ajudat més?|¿Mi compañero ha acertado la figura? ¿Qué vista le ha ayudado más?' }] }
    ]
  },
  /* ---------- Sessió 3 · Els eixos x, y, z ---------- */
  'm1-3': {
    obj: ["L'alumne/a identifica els eixos x, y i z i el sentit positiu de cada un.|El alumno/a identifica los ejes x, y y z y el sentido positivo de cada uno.", "L'alumne/a llegeix la posició d'una peça amb coordenades, també amb números negatius.|El alumno/a lee la posición de una pieza con coordenadas, también con números negativos.",
      "L'alumne/a col·loca una peça en un punt donat amb els camps numèrics o arrossegant-la.|El alumno/a coloca una pieza en un punto dado con los campos numéricos o arrastrándola.", "L'alumne/a detecta i corregeix peces que floten o que s'enfonsen a la placa.|El alumno/a detecta y corrige piezas que flotan o que se hunden en la placa."],
    comp: ['Matemàtiques, sentit espacial: coordenades i posició en el pla i en l\'espai|Matemáticas, sentido espacial: coordenadas y posición en el plano y en el espacio', 'Matemàtiques, sentit numèric: els nombres negatius en una recta|Matemáticas, sentido numérico: los números negativos en una recta', 'Tecnologia i digitalització: precisió en el disseny assistit per ordinador|Tecnología y digitalización: precisión en el diseño asistido por ordenador', 'Pensament computacional: donar instruccions exactes a una màquina|Pensamiento computacional: dar instrucciones exactas a una máquina'],
    vocab: [['Eix|Eje', 'Una línia que marca una direcció: x, y o z.|Una línea que marca una dirección: x, y o z.'], ['Coordenades|Coordenadas', 'Tres números (x, y, z) que diuen on és un punt.|Tres números (x, y, z) que dicen dónde está un punto.'], ['Origen|Origen', 'El punt (0, 0, 0): el centre de la placa.|El punto (0, 0, 0): el centro de la placa.'], ['Número negatiu|Número negativo', "Un número més petit que 0: a l'altre costat de l'origen.|Un número menor que 0: al otro lado del origen."], ['Fantasma|Fantasma', 'El model transparent que mostra on ha d\'anar la peça.|El modelo transparente que muestra dónde tiene que ir la pieza.']],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Els eixos x, y, z»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Los ejes x, y, z»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', "Cinta adhesiva de dos colors per fer els eixos x i y a terra|Cinta adhesiva de dos colores para hacer los ejes x e y en el suelo"],
      imprimir: ['Targetes de coordenades|Tarjetas de coordenadas', 'Fitxa: on és cada peça?|Ficha: ¿dónde está cada pieza?'], prep: ['Enganxar a terra dues tires de cinta que es creuin (vermella per a x, verda per a y) i marcar cada pas amb un tros petit.|Pegar en el suelo dos tiras de cinta que se crucen (roja para x, verde para y) y marcar cada paso con un trozo pequeño.', 'Imprimir i retallar les targetes de coordenades.|Imprimir y recortar las tarjetas de coordenadas.', 'Provar abans el repte de la torre: cal escriure z = 20.|Probar antes el reto de la torre: hay que escribir z = 20.'] },
    plan: [
      { min: 5, t: 'Recordem les vistes|Recordamos las vistas', fase: 'inici', fa: "Repàs ràpid de les vistes de la sessió anterior. Planteja el problema del dia: com li diem a la Nuvi on va una peça si no podem dir «una mica a la dreta»?|Repaso rápido de las vistas de la sesión anterior. Plantea el problema del día: ¿cómo le decimos a Nuvi dónde va una pieza si no podemos decir «un poco a la derecha»?",
        diu: ['Com explicaríeu a algú per telèfon on és la vostra cadira?|¿Cómo explicaríais a alguien por teléfono dónde está vuestra silla?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Els eixos i les coordenades|Los ejes y las coordenadas', fase: 'teoria', fa: "Presenta els tres eixos amb els seus colors i l'origen. Fes servir el model dels quatre cubs per llegir coordenades. Dedica temps als números negatius: a l'esquerra i davant de l'origen. Explica que a la pestanya Posició la z és l'alçada de la base.|Presenta los tres ejes con sus colores y el origen. Usa el modelo de los cuatro cubos para leer coordenadas. Dedica tiempo a los números negativos: a la izquierda y delante del origen. Explica que en la pestaña Posición la z es la altura de la base.",
        diu: ["On és el cub vermell? I el verd?|¿Dónde está el cubo rojo? ¿Y el verde?", 'Si x = 20 és a la dreta, on és x = −20?|Si x = 20 está a la derecha, ¿dónde está x = −20?'], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'La placa humana|La placa humana', fase: 'desconnectat', fa: "Amb la cinta a terra: un alumne/a treu una targeta de coordenades i la llegeix; un altre surt de l'origen i hi camina (primer x, després y). Per a la z, aixeca els braços. La resta comprova si ha anat al lloc bo.|Con la cinta en el suelo: un alumno/a saca una tarjeta de coordenadas y la lee; otro sale del origen y camina hasta allí (primero x, después y). Para la z, levanta los brazos. El resto comprueba si ha ido al sitio correcto.",
        diu: ['Primer la x, després la y: com a la placa del taller.|Primero la x, después la y: como en la placa del taller.', 'Una x negativa vol dir cap a quin costat?|Una x negativa quiere decir ¿hacia qué lado?'], slides: ['s8'], app: 'Encara no: activitat al terra de l\'aula.|Todavía no: actividad en el suelo del aula.', org: 'Petits grups|Pequeños grupos' },
      { min: 22, t: "A l'ordinador: col·loca i arregla|En el ordenador: coloca y arregla", fase: 'ordinador', fa: "Fan la sessió a l'app: llegir coordenades, moure el cub al fantasma, apilar i arreglar models que floten. Comprova que fan servir els camps numèrics i no només l'arrossegament: la precisió és l'objectiu.|Hacen la sesión en la app: leer coordenadas, mover el cubo al fantasma, apilar y arreglar modelos que flotan. Comprueba que usan los campos numéricos y no solo el arrastre: la precisión es el objetivo.",
        diu: ['Quin número has de canviar per pujar-lo? I per portar-lo a la dreta?|¿Qué número tienes que cambiar para subirlo? ¿Y para llevarlo a la derecha?', 'Per què la Nuvi no podria fer una peça que flota?|¿Por qué Nuvi no podría hacer una pieza que flota?'], slides: ['s9', 's10', 's11'], app: "Sessió «Els eixos x, y, z», fins a «L'encàrrec de la biblioteca».|Sesión «Los ejes x, y, z», hasta «El encargo de la biblioteca».", org: 'Individual|Individual' },
      { min: 6, t: "L'encàrrec de la biblioteca|El encargo de la biblioteca", fase: 'crea', fa: "Han de complir les coordenades de l'encàrrec però trien les formes i els colors. Quan les comprovacions es marquen, ho desen al portafoli.|Tienen que cumplir las coordenadas del encargo pero eligen las formas y los colores. Cuando las comprobaciones se marcan, lo guardan en el portafolio.",
        diu: ['Les comprovacions et diuen si les peces són al lloc: mira-les.|Las comprobaciones te dicen si las piezas están en su sitio: míralas.'], slides: ['s12'], app: "Pas «L'encàrrec de la biblioteca».|Paso «El encargo de la biblioteca».", org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: 'Repassa els tres eixos i el significat de z = 0. Tiquet de sortida.|Repasa los tres ejes y el significado de z = 0. Ticket de salida.',
        diu: ['Quin eix va cap amunt? Què vol dir z = 0?|¿Qué eje va hacia arriba? ¿Qué quiere decir z = 0?'], slides: ['s13', 's14'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Confon l'eix x amb l'eix y.|Confunde el eje x con el eje y.", "Recorda-li els colors: la línia vermella de la placa és l'eix x; la verda, l'eix y. Fes que segueixi la línia amb el dit.|Recuérdale los colores: la línea roja de la placa es el eje x; la verde, el eje y. Haz que siga la línea con el dedo."],
      ['Escriu 20 en lloc de −20.|Escribe 20 en lugar de −20.', "Pregunta-li a quin costat de l'origen és el fantasma. Si és a l'esquerra o davant, el número porta un signe menys.|Pregúntale a qué lado del origen está el fantasma. Si está a la izquierda o delante, el número lleva un signo menos."],
      ['Per apilar, posa z = 10 (el centre) en lloc de z = 20 (la base).|Para apilar, pone z = 10 (el centro) en lugar de z = 20 (la base).', "Recorda que, a Posició, la z és on comença la peça per baix: just on acaba la de sota.|Recuerda que, en Posición, la z es donde empieza la pieza por abajo: justo donde acaba la de debajo."],
      ['Arrossega la peça i queda a mig quadret del fantasma.|Arrastra la pieza y queda a medio cuadrito del fantasma.', 'Que escrigui el número exacte al camp: arrossegar és ràpid, però els números són exactes.|Que escriba el número exacto en el campo: arrastrar es rápido, pero los números son exactos.']],
    diff: { mes: "Fer una escala de 4 graons amb cubs de 20 mm escrivint només coordenades. Inventar coordenades per a un company i comprovar-les a la vista de dalt.|Hacer una escalera de 4 peldaños con cubos de 20 mm escribiendo solo coordenadas. Inventar coordenadas para un compañero y comprobarlas en la vista de arriba.",
      menys: 'Treballar primer només amb x (y = 0) i després afegir la y. Tenir la placa de la fitxa al costat per comptar quadrets.|Trabajar primero solo con x (y = 0) y después añadir la y. Tener la placa de la ficha al lado para contar cuadritos.' },
    aval: { ticket: ['Quin eix va cap amunt?|¿Qué eje va hacia arriba?', 'On és una peça a x = 0, y = 0?|¿Dónde está una pieza en x = 0, y = 0?'],
      rubric: [['Els eixos|Los ejes', 'Diu la direcció de x, y i z i el sentit positiu.|Dice la dirección de x, y y z y el sentido positivo.', 'Reconeix la z, però confon x i y.|Reconoce la z, pero confunde x e y.'],
        ['Coordenades i negatius|Coordenadas y negativos', 'Llegeix i escriu coordenades amb negatius sense errors.|Lee y escribe coordenadas con negativos sin errores.', "S'oblida del signe menys o de l'ordre (x, y).|Se olvida del signo menos o del orden (x, y)."],
        ['Peces a la placa|Piezas en la placa', 'Detecta i arregla peces que floten o s\'enfonsen.|Detecta y arregla piezas que flotan o se hunden.', 'Ho arregla amb ajuda o a ull, sense fer servir la z.|Lo arregla con ayuda o a ojo, sin usar la z.']] },
    casa: "Repte per a casa, «On és?»: dibuixa una quadrícula en un paper amb els eixos al mig i amaga-hi un tresor. L'altra persona l'ha de trobar dient coordenades.|Reto para casa, «¿Dónde está?»: dibuja una cuadrícula en un papel con los ejes en el medio y esconde un tesoro. La otra persona tiene que encontrarlo diciendo coordenadas.",
    intro: "Sessió clau del nivell: a partir d'ara totes les peces es col·loquen amb números. Val la pena que l'activitat a terra quedi ben assolida abans de passar a l'ordinador.|Sesión clave del nivel: a partir de ahora todas las piezas se colocan con números. Vale la pena que la actividad en el suelo quede bien asumida antes de pasar al ordenador.",
    claus: ["L'eix x va d'esquerra a dreta, l'eix y de davant cap a darrere i l'eix z cap amunt.|El eje x va de izquierda a derecha, el eje y de delante hacia detrás y el eje z hacia arriba.", "L'origen (0, 0, 0) és el centre de la placa.|El origen (0, 0, 0) es el centro de la placa.", 'Els números negatius indiquen l\'altre costat de l\'origen.|Los números negativos indican el otro lado del origen.', 'A la pestanya Posició, z és l\'alçada de la base: z = 0 vol dir que la peça toca la placa.|En la pestaña Posición, z es la altura de la base: z = 0 quiere decir que la pieza toca la placa.'],
    prev: ['Haver fet la sessió «Benvinguts al taller 3D» (girar la vista).|Haber hecho la sesión «Bienvenidos al taller 3D» (girar la vista).', 'Conèixer els nombres fins a 100.|Conocer los números hasta 100.', 'Els nombres negatius es presenten a la sessió: no cal saber-los abans.|Los números negativos se presentan en la sesión: no hace falta saberlos antes.'],
    faq: [['Per què la z és la base i no el centre de la peça?|¿Por qué la z es la base y no el centro de la pieza?', "Perquè és més fàcil pensar a quina alçada comença una peça: z = 0 és a terra, i per apilar-ne una a sobre d'una altra de 20 mm, z = 20.|Porque es más fácil pensar a qué altura empieza una pieza: z = 0 es el suelo, y para apilar una encima de otra de 20 mm, z = 20."],
      ['Per què la y va cap al fons i no cap amunt, com a la pissarra?|¿Por qué la y va hacia el fondo y no hacia arriba, como en la pizarra?', "Perquè la placa és a terra, com un full sobre la taula. Cap amunt hi ha la tercera direcció, la z. Les impressores 3D fan servir aquest mateix conveni.|Porque la placa está en el suelo, como una hoja sobre la mesa. Hacia arriba está la tercera dirección, la z. Las impresoras 3D usan esta misma convención."],
      ["Què passa si una peça surt de la placa?|¿Qué pasa si una pieza sale de la placa?", 'Al taller es pot dibuixar, però la impressora no la podria fer: la placa fa 200 × 200 mm, de −100 a 100.|En el taller se puede dibujar, pero la impresora no podría hacerla: la placa mide 200 × 200 mm, de −100 a 100.']],
    tec: [['No es pot escriure el signe menys al camp.|No se puede escribir el signo menos en el campo.', 'Al teclat del mòbil, el signe menys és a la pestanya dels números. També es pot fer servir el botó − del costat.|En el teclado del móvil, el signo menos está en la pestaña de los números. También se puede usar el botón − del lado.'],
      ["El cub és dins del fantasma però la comprovació no es marca.|El cubo está dentro del fantasma pero la comprobación no se marca.", "Cal que hi sigui gairebé exacte: comproveu els tres números de Posició. Potser la z no és 0.|Tiene que estar casi exacto: comprobad los tres números de Posición. Quizá la z no es 0."],
      ['La peça es mou de 5 en 5 mm i no arriba al lloc.|La pieza se mueve de 5 en 5 mm y no llega al sitio.', 'El botó de la quadrícula (a sota de la vista) canvia el pas: 1, 5 o 10 mm.|El botón de la cuadrícula (debajo de la vista) cambia el paso: 1, 5 o 10 mm.']],
    extra: ['Fer una «batalla naval 3D» amb coordenades x, y, z en paper.|Hacer una «batalla naval 3D» con coordenadas x, y, z en papel.', "Dibuixar a la vista de dalt les coordenades de quatre peces i que un company les col·loqui.|Dibujar en la vista de arriba las coordenadas de cuatro piezas y que un compañero las coloque.", 'Buscar on es fan servir coordenades a la vida real (mapes, GPS, escacs).|Buscar dónde se usan coordenadas en la vida real (mapas, GPS, ajedrez).'],
    trans: ['Sessió següent: projecte de la primera escultura.|Sesión siguiente: proyecto de la primera escultura.', 'Matemàtiques: els nombres enters i els eixos de coordenades.|Matemáticas: los números enteros y los ejes de coordenadas.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Els eixos x, y, z|Los ejes x, y, z', x: 'Números perquè la Nuvi sàpiga on va cada peça|Números para que Nuvi sepa dónde va cada pieza', nota: "Presenta l'encàrrec de la biblioteca: peces col·locades exactament.|Presenta el encargo de la biblioteca: piezas colocadas exactamente." },
      { id: 's2', k: 'repas', t: 'Recordem les vistes|Recordamos las vistas', punts: ['Davant (alçat)|Delante (alzado)', 'Dalt (planta)|Arriba (planta)', 'Costat (perfil)|Lado (perfil)'], nota: 'Demana exemples de què es veu des de cada vista amb la casa de la Nuvi.|Pide ejemplos de qué se ve desde cada vista con la casa de Nuvi.' },
      { id: 's3', k: 'anim', t: 'Tres eixos|Tres ejes', anim: 'm3axes', x: 'x vermell, y verd, z blau.|x rojo, y verde, z azul.', nota: 'Associa cada eix al seu color: els veuran a la placa del taller.|Asocia cada eje a su color: los verán en la placa del taller.' },
      { id: 's4', k: 'media', t: "L'origen i els quatre cubs|El origen y los cuatro cubos", x: 'On és cada cub?|¿Dónde está cada cubo?', media: { k: 'model', model: { parts: EIXOS } }, nota: 'Llegiu junts: gris (0, 0, 0), vermell (40, 0, 0), verd (0, 40, 0) i blau (0, 0, 40).|Leed juntos: gris (0, 0, 0), rojo (40, 0, 0), verde (0, 40, 0) y azul (0, 0, 40).' },
      { id: 's5', k: 'media', t: 'Números negatius|Números negativos', x: "A l'esquerra i davant de l'origen, els números són negatius.|A la izquierda y delante del origen, los números son negativos.", media: { k: 'model', model: { parts: PUNTS }, view: 'top' }, nota: 'Demana les coordenades dels quatre cilindres. El verd és (−20, −20).|Pide las coordenadas de los cuatro cilindros. El verde es (−20, −20).' },
      { id: 's6', k: 'concepte', t: 'La posició d\'una peça|La posición de una pieza', x: 'x i y: on és el centre de la peça a la placa. z: a quina alçada és la seva base.|x e y: dónde está el centro de la pieza en la placa. z: a qué altura está su base.', nota: "Insisteix en la z: z = 0 vol dir que toca la placa.|Insiste en la z: z = 0 quiere decir que toca la placa." },
      { id: 's7', k: 'pregunta', t: "Si apilo un cub de 20 mm a sobre d'un altre, quina és la seva z?|Si apilo un cubo de 20 mm encima de otro, ¿cuál es su z?", x: 'Pista: on acaba el cub de sota?|Pista: ¿dónde acaba el cubo de debajo?', nota: 'Resposta: z = 20. Ho necessitaran al repte de la torre.|Respuesta: z = 20. Lo necesitarán en el reto de la torre.' },
      { id: 's8', k: 'activitat', t: 'La placa humana|La placa humana', timer: 8, punts: ['Llegeix la targeta: x, y i z.|Lee la tarjeta: x, y y z.', "Surt de l'origen i camina: primer x, després y.|Sal del origen y camina: primero x, después y.", 'Per a la z, aixeca els braços.|Para la z, levanta los brazos.'], nota: 'En grups de 4: una persona llegeix, una camina, dues comproven.|En grupos de 4: una persona lee, una camina, dos comprueban.' },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['Mou el cub al fantasma.|Mueve el cubo al fantasma.', 'Fes una torre de dos cubs.|Haz una torre de dos cubos.', 'Arregla el pont que flota.|Arregla el puente que flota.'], nota: 'Recorda que els camps numèrics són a la pestanya Posició.|Recuerda que los campos numéricos están en la pestaña Posición.' },
      { id: 's10', k: 'media', t: 'La torre|La torre', x: 'El cub de dalt comença a z = 20.|El cubo de arriba empieza en z = 20.', media: { k: 'model', model: { parts: [P('a', 'box', [20, 20, 20], [0, 0, 10], '#3D7BF4'), P('b', 'box', [20, 20, 20], [0, 0, 30], '#7C5CFF')] }, view: 'front' }, nota: "Fes-ho a la pissarra per a qui s'encalli: la base del lila és on acaba el blau.|Hazlo en la pizarra para quien se atasque: la base del lila es donde acaba el azul." },
      { id: 's11', k: 'concepte', t: 'Peces que floten|Piezas que flotan', x: 'La impressora construeix de baix a dalt: una peça que no toca res no es pot imprimir.|La impresora construye de abajo arriba: una pieza que no toca nada no se puede imprimir.', nota: 'Connecta amb la idea de les capes de la primera sessió.|Conecta con la idea de las capas de la primera sesión.' },
      { id: 's12', k: 'repte', t: "L'encàrrec de la biblioteca|El encargo de la biblioteca", punts: ['Una peça a x = −30 i una a x = 30.|Una pieza en x = −30 y una en x = 30.', 'Una peça al mig, més alta.|Una pieza en el medio, más alta.', 'Totes toquen la placa.|Todas tocan la placa.'], nota: 'Formes i colors lliures. Les comprovacions es marquen soles.|Formas y colores libres. Las comprobaciones se marcan solas.' },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['x d\'esquerra a dreta, y cap al fons, z cap amunt.|x de izquierda a derecha, y hacia el fondo, z hacia arriba.', "L'origen és el centre; els negatius van a l'altre costat.|El origen es el centro; los negativos van al otro lado.", 'z = 0 vol dir que la peça toca la placa.|z = 0 quiere decir que la pieza toca la placa.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Quin eix va cap amunt?|¿Qué eje va hacia arriba?', 'On és una peça a x = 0, y = 0?|¿Dónde está una pieza en x = 0, y = 0?'], nota: 'Oral o amb els dits: x (braç), y (endavant), z (amunt).|Oral o con los dedos: x (brazo), y (adelante), z (arriba).' }
    ],
    print: [
      { id: 'p1', t: 'Targetes de coordenades|Tarjetas de coordenadas', k: 'targetes', intro: "Retalleu-les i barregeu-les. Cada pas de la placa humana és una unitat.|Recortadlas y mezcladlas. Cada paso de la placa humana es una unidad.",
        items: [{ t: '(2, 1, 0)|(2, 1, 0)', n: 1 }, { t: '(−2, 1, 0)|(−2, 1, 0)', n: 1 }, { t: '(0, −2, 1)|(0, −2, 1)', n: 1 }, { t: '(3, −1, 2)|(3, −1, 2)', n: 1 }, { t: '(−1, −1, 1)|(−1, −1, 1)', n: 1 }, { t: '(0, 3, 0)|(0, 3, 0)', n: 1 }, { t: '(−3, 0, 2)|(−3, 0, 2)', n: 1 }, { t: '(1, 2, 1)|(1, 2, 1)', n: 1 }] },
      { id: 'p2', t: 'Fitxa: on és cada peça?|Ficha: ¿dónde está cada pieza?', k: 'fitxa', intro: "Escriu les coordenades x i y de cada peça. Cada quadret fa 10 mm.|Escribe las coordenadas x e y de cada pieza. Cada cuadrito mide 10 mm.",
        items: [{ q: "Una peça és 3 quadrets a la dreta de l'origen. Quina és la seva x?|Una pieza está 3 cuadritos a la derecha del origen. ¿Cuál es su x?", sol: 'x = 30|x = 30' }, { q: "Una peça és 2 quadrets a l'esquerra i 1 cap al fons. Quines són x i y?|Una pieza está 2 cuadritos a la izquierda y 1 hacia el fondo. ¿Cuáles son x e y?", sol: 'x = −20, y = 10|x = −20, y = 10' },
          { q: "Un cub de 20 mm és a sobre d'un altre cub de 20 mm. Quina és la z del de dalt?|Un cubo de 20 mm está encima de otro cubo de 20 mm. ¿Cuál es la z del de arriba?", sol: 'z = 20|z = 20' }] }
    ]
  },
  /* ---------- Sessió 4 · Projecte: la meva primera escultura ---------- */
  'm1-4': {
    obj: ["L'alumne/a dissenya una escultura 3D de 3 a 5 formes seguint un procés: idea, esbós, model i revisió.|El alumno/a diseña una escultura 3D de 3 a 5 formas siguiendo un proceso: idea, boceto, modelo y revisión.",
      "L'alumne/a col·loca peces a sobre d'altres fent servir la coordenada z i comprova que cap no flota.|El alumno/a coloca piezas encima de otras usando la coordenada z y comprueba que ninguna flota.",
      "L'alumne/a revisa el seu model des de totes les vistes i en tria i justifica una de preferida.|El alumno/a revisa su modelo desde todas las vistas y elige y justifica una preferida.",
      "L'alumne/a dona i rep una opinió respectuosa sobre una escultura d'un company.|El alumno/a da y recibe una opinión respetuosa sobre una escultura de un compañero."],
    comp: ['Matemàtiques, sentit espacial: composició de cossos, posició i vistes|Matemáticas, sentido espacial: composición de cuerpos, posición y vistas', 'Tecnologia i digitalització: procés de disseny i fabricació d\'un prototip|Tecnología y digitalización: proceso de diseño y fabricación de un prototipo',
      'Educació artística: volum, equilibri, contrast i color en una escultura|Educación artística: volumen, equilibrio, contraste y color en una escultura', 'Competència personal i social: revisar la pròpia feina i donar retroacció|Competencia personal y social: revisar el propio trabajo y dar retroalimentación'],
    vocab: [['Escultura|Escultura', 'Obra en tres dimensions que es pot mirar per tots els costats.|Obra en tres dimensiones que se puede mirar por todos los lados.'], ['Esbós|Boceto', 'Dibuix ràpid per pensar una idea abans de construir-la.|Dibujo rápido para pensar una idea antes de construirla.'],
      ['Equilibri|Equilibrio', "Quan una escultura s'aguanta bé i no sembla que hagi de caure.|Cuando una escultura se aguanta bien y no parece que vaya a caer."], ['Contrast|Contraste', 'Combinar coses diferents: rodó i punxegut, alt i baix, clar i fosc.|Combinar cosas distintas: redondo y puntiagudo, alto y bajo, claro y oscuro.'],
      ['Revisar|Revisar', 'Mirar la feina feta per trobar què es pot millorar.|Mirar el trabajo hecho para encontrar qué se puede mejorar.'], ['Flotar|Flotar', 'Quan una peça no toca ni la placa ni cap altra peça.|Cuando una pieza no toca ni la placa ni ninguna otra pieza.']],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Projecte: la meva primera escultura»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Proyecto: mi primera escultura»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Llapis, goma i colors per a l\'esbós|Lápiz, goma y colores para el boceto', "Si n'hi ha, una peça impresa en 3D o una figureta per ensenyar|Si hay, una pieza impresa en 3D o una figurita para enseñar"],
      imprimir: ["Esbós de l'escultura (un per alumne/a)|Boceto de la escultura (uno por alumno/a)", "Fitxa del crític/a d'art (una per alumne/a)|Ficha del crítico/a de arte (una por alumno/a)"],
      prep: ["Decidir amb el centre on es farà l'exposició (física o en una pantalla) i si s'imprimirà alguna escultura.|Decidir con el centro dónde se hará la exposición (física o en una pantalla) y si se imprimirá alguna escultura.", 'Provar abans el pas d\'arreglar la bola: cal posar z = 37.|Probar antes el paso de arreglar la bola: hay que poner z = 37.',
        "Preparar una manera de veure els projectes desats (el portafoli de l'app a la pissarra digital) per a la galeria final.|Preparar una manera de ver los proyectos guardados (el portafolio de la app en la pizarra digital) para la galería final."] },
    plan: [
      { min: 5, t: "L'exposició del taller|La exposición del taller", fase: 'inici', fa: "Presenta el projecte: una exposició d'escultures petites a l'aparador de la biblioteca. Ensenya l'escultura d'exemple girant-la a la pissarra digital i pregunta què la fa bonica de tots els costats.|Presenta el proyecto: una exposición de esculturas pequeñas en el escaparate de la biblioteca. Enseña la escultura de ejemplo girándola en la pizarra digital y pregunta qué la hace bonita desde todos los lados.",
        diu: ["Què té una escultura que no té un dibuix?|¿Qué tiene una escultura que no tiene un dibujo?", 'Quantes formes veieu en aquesta? Quines?|¿Cuántas formas veis en esta? ¿Cuáles?'], slides: ['s1', 's2', 's3'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 8, t: 'Com es dissenya una escultura|Cómo se diseña una escultura', fase: 'teoria', fa: "Tres idees curtes: equilibri (base ampla a baix), contrast (rodó i punxegut, alt i baix, dos o tres colors) i el procés de disseny (idea, esbós, model, revisió). Acaba amb la norma de la Nuvi: res no pot flotar.|Tres ideas cortas: equilibrio (base ancha abajo), contraste (redondo y puntiagudo, alto y bajo, dos o tres colores) y el proceso de diseño (idea, boceto, modelo, revisión). Acaba con la norma de Nuvi: nada puede flotar.",
        diu: ['Per què la bola grossa de dalt trontolla?|¿Por qué la bola grande de arriba se tambalea?', 'Què passaria si la Nuvi hagués de fer una peça que flota?|¿Qué pasaría si Nuvi tuviera que hacer una pieza que flota?'], slides: ['s4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: "L'esbós|El boceto", fase: 'desconnectat', fa: "Cada alumne/a pensa una idea i la dibuixa de davant a la quadrícula de l'esbós, amb la llista de formes i colors. Als cinc minuts, ensenya l'esbós al company del costat, que li fa una pregunta o un suggeriment.|Cada alumno/a piensa una idea y la dibuja de delante en la cuadrícula del boceto, con la lista de formas y colores. A los cinco minutos, enseña el boceto al compañero de al lado, que le hace una pregunta o una sugerencia.",
        diu: ["No cal que sigui bonic: ha de servir per pensar.|No hace falta que sea bonito: tiene que servir para pensar.", 'Quina peça va a baix de tot? Què hi ha a sobre?|¿Qué pieza va abajo del todo? ¿Qué hay encima?'], slides: ['s8'], app: 'Encara no: esbós en paper.|Todavía no: boceto en papel.', org: 'Individual i per parelles|Individual y por parejas' },
      { min: 12, t: "A l'ordinador: apilar sense que res floti|En el ordenador: apilar sin que nada flote", fase: 'ordinador', fa: "Fan els primers passos de l'app: trobar i arreglar la bola que flota i els reptes del tòtem i de l'arc. Són l'entrenament per a l'escultura: posar cada peça a la z on acaba la de sota.|Hacen los primeros pasos de la app: encontrar y arreglar la bola que flota y los retos del tótem y del arco. Son el entrenamiento para la escultura: poner cada pieza en la z donde acaba la de debajo.",
        diu: ['On acaba la peça de sota? Aquesta és la z de la de dalt.|¿Dónde acaba la pieza de debajo? Esa es la z de la de arriba.'], slides: ['s9', 's10', 's11'], app: "Sessió «Projecte: la meva primera escultura», fins al repte de l'arc.|Sesión «Proyecto: mi primera escultura», hasta el reto del arco.", org: 'Individual|Individual' },
      { min: 20, t: "L'escultura|La escultura", fase: 'crea', fa: "Cada alumne/a construeix la seva escultura seguint l'esbós: de 3 a 5 formes, almenys 2 colors, tot connectat i tocant la placa. Les comprovacions es marquen soles; quan estan totes, es desa. Després, fan la revisió de crític/a d'art a l'app i omplen la fitxa amb un company.|Cada alumno/a construye su escultura siguiendo el boceto: de 3 a 5 formas, al menos 2 colores, todo conectado y tocando la placa. Las comprobaciones se marcan solas; cuando están todas, se guarda. Después, hacen la revisión de crítico/a de arte en la app y rellenan la ficha con un compañero.",
        diu: ["Mira-la de davant, de dalt i del costat abans de desar-la.|Mírala de delante, de arriba y del lado antes de guardarla.", "Si l'esbós no funciona a l'ordinador, el pots canviar: els dissenyadors també ho fan.|Si el boceto no funciona en el ordenador, lo puedes cambiar: los diseñadores también lo hacen."], slides: ['s12', 's13'], app: "Passos «La teva escultura per a l'exposició» i «Ara fes de crític/a d'art».|Pasos «Tu escultura para la exposición» y «Ahora haz de crítico/a de arte».", org: 'Individual i per parelles|Individual y por parejas' },
      { min: 5, t: 'La galeria|La galería', fase: 'tancament', fa: "Projecta algunes escultures desades (amb permís de l'autor/a) i que cada autor/a digui el nom i la vista preferida. Recull què han après del procés i explica que la Nuvi en podrà imprimir alguna.|Proyecta algunas esculturas guardadas (con permiso del autor/a) y que cada autor/a diga el nombre y la vista preferida. Recoge qué han aprendido del proceso y explica que Nuvi podrá imprimir alguna.",
        diu: ['Què us ha agradat de l\'escultura del company?|¿Qué os ha gustado de la escultura del compañero?', "Què faríeu diferent la propera vegada?|¿Qué haríais diferente la próxima vez?"], slides: ['s14', 's15', 's16'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Posa una peça a sobre d'una altra amb la z del centre (10) en lloc de la de la base (20).|Pone una pieza encima de otra con la z del centro (10) en lugar de la de la base (20).", 'Recorda-li que, a Posició, la z és on comença la peça per baix: just on acaba la de sota. Que miri la peça de sota a la pestanya Mida.|Recuérdale que, en Posición, la z es donde empieza la pieza por abajo: justo donde acaba la de debajo. Que mire la pieza de debajo en la pestaña Medida.'],
      ["Deixa una peça flotant sense adonar-se'n.|Deja una pieza flotando sin darse cuenta.", "La comprovació «És una sola peça» no es marca. Que miri l'escultura des de davant i des del costat buscant un forat d'aire.|La comprobación «Es una sola pieza» no se marca. Que mire la escultura desde delante y desde el lado buscando un hueco de aire."],
      ["Fa una escultura amb moltes més peces de les que demana l'encàrrec.|Hace una escultura con muchas más piezas de las que pide el encargo.", "L'encàrrec diu de 3 a 5 formes: limitar-se també és part del disseny. Que triï les que més li agradin.|El encargo dice de 3 a 5 formas: limitarse también es parte del diseño. Que elija las que más le gusten."],
      ["Es bloqueja: no sap què fer i esborra l'esbós una vegada i una altra.|Se bloquea: no sabe qué hacer y borra el boceto una y otra vez.", "Proposa-li partir d'una cosa coneguda (un animal, un arbre, un trofeu) o de tres formes a l'atzar i que n'hi busqui un significat.|Propónle partir de algo conocido (un animal, un árbol, un trofeo) o de tres formas al azar y que les busque un significado."]],
    diff: { mes: "Fer una escultura que es vegi molt diferent des de cada vista (per exemple, una cara de davant i una estrella de dalt) o que tingui un forat de banda a banda, com l'arc.|Hacer una escultura que se vea muy distinta desde cada vista (por ejemplo, una cara de delante y una estrella de arriba) o que tenga un hueco de lado a lado, como el arco.",
      menys: "Començar a partir del tòtem del repte i canviar-ne formes i colors. Fer l'esbós només amb la llista de formes, sense dibuix.|Empezar a partir del tótem del reto y cambiar sus formas y colores. Hacer el boceto solo con la lista de formas, sin dibujo." },
    aval: { ticket: ['Digues un pas del procés de disseny.|Di un paso del proceso de diseño.', 'Per què una peça no pot flotar?|¿Por qué una pieza no puede flotar?'],
      rubric: [['Procés de disseny|Proceso de diseño', "Fa l'esbós, el segueix (o el millora) i revisa el model.|Hace el boceto, lo sigue (o lo mejora) y revisa el modelo.", 'Fa el model sense esbós o no el revisa.|Hace el modelo sin boceto o no lo revisa.'],
        ["L'escultura|La escultura", 'Té de 3 a 5 formes, toca la placa i no hi flota res.|Tiene de 3 a 5 formas, toca la placa y no flota nada.', "Li falta alguna condició (flota alguna peça, en té massa poques o massa).|Le falta alguna condición (flota alguna pieza, tiene demasiado pocas o demasiadas)."],
        ['Mirar i explicar|Mirar y explicar', 'Mira el model des de totes les vistes i justifica la vista preferida.|Mira el modelo desde todas las vistas y justifica la vista preferida.', 'Tria una vista, però no sap dir per què.|Elige una vista, pero no sabe decir por qué.']] },
    casa: "Ensenya l'escultura (al portafoli de l'app) a algú de casa i explica-li com l'has feta: idea, esbós, model i revisió. Quina vista li agrada més?|Enseña la escultura (en el portafolio de la app) a alguien de casa y explícale cómo la has hecho: idea, boceto, modelo y revisión. ¿Qué vista le gusta más?",
    intro: "Primer projecte del curs. Tanca la unitat de l'espai 3D: fa servir les vistes, les coordenades i la idea que res no pot flotar. Més que el resultat, importa que visquin el procés de disseny complet i que revisin la seva feina amb ulls de crític/a.|Primer proyecto del curso. Cierra la unidad del espacio 3D: usa las vistas, las coordenadas y la idea de que nada puede flotar. Más que el resultado, importa que vivan el proceso de diseño completo y que revisen su trabajo con ojos de crítico/a.",
    claus: ['Una escultura es dissenya pensant en totes les vistes.|Una escultura se diseña pensando en todas las vistas.', 'El procés de disseny és idea, esbós, model i revisió, i es pot repetir.|El proceso de diseño es idea, boceto, modelo y revisión, y se puede repetir.',
      'Una base ampla dona equilibri; el contrast de formes i colors dona vida.|Una base ancha da equilibrio; el contraste de formas y colores da vida.', "Per imprimir, cada peça ha de tocar la placa o una altra peça.|Para imprimir, cada pieza tiene que tocar la placa u otra pieza."],
    prev: ['Les sessions «Davant, dalt i costat» i «Els eixos x, y, z» (vistes i coordenades).|Las sesiones «Delante, arriba y lado» y «Los ejes x, y, z» (vistas y coordenadas).', 'Saber afegir formes de la paleta i canviar-ne la posició.|Saber añadir formas de la paleta y cambiar su posición.', "Saber que la z de la pestanya Posició és l'alçada de la base.|Saber que la z de la pestaña Posición es la altura de la base."],
    faq: [['Podem imprimir les escultures?|¿Podemos imprimir las esculturas?', "Sí, si el centre té una impressora 3D: totes compleixen la norma de no flotar. Amb una escultura petita de 4-5 cm, la impressió dura una estona; a la unitat 6 aprendrem a preparar-les bé.|Sí, si el centro tiene una impresora 3D: todas cumplen la norma de no flotar. Con una escultura pequeña de 4-5 cm, la impresión dura un rato; en la unidad 6 aprenderemos a prepararlas bien."],
      ["Per què només 5 formes?|¿Por qué solo 5 formas?", "Perquè l'encàrrec ho demana i perquè triar és part del disseny. Amb poques formes ben pensades, l'escultura es llegeix millor.|Porque el encargo lo pide y porque elegir es parte del diseño. Con pocas formas bien pensadas, la escultura se lee mejor."],
      ["I si la meva escultura no s'assembla a l'esbós?|¿Y si mi escultura no se parece al boceto?", "No passa res: l'esbós és per començar a pensar. Si al model se t'ha acudit una idea millor, és part del procés.|No pasa nada: el boceto es para empezar a pensar. Si en el modelo se te ha ocurrido una idea mejor, es parte del proceso."]],
    tec: [["No es pot desar: el botó de desar està desactivat.|No se puede guardar: el botón de guardar está desactivado.", 'Encara falta alguna comprovació. La llista de sota la vista diu quina: sovint és «És una sola peça» (alguna cosa flota).|Todavía falta alguna comprobación. La lista de debajo de la vista dice cuál: a menudo es «Es una sola pieza» (algo flota).'],
      ["L'estrella o el cor queden estirats.|La estrella o el corazón quedan estirados.", "S'han canviat les mides x i y de manera diferent. Amb el botó Proporcional les mides canvien alhora.|Se han cambiado las medidas x e y de manera distinta. Con el botón Proporcional las medidas cambian a la vez."],
      ["Una peça ha desaparegut dins d'una altra.|Una pieza ha desaparecido dentro de otra.", 'És a dins: es pot tocar l\'altra peça i moure-la una mica, o desfer el darrer canvi amb la fletxa.|Está dentro: se puede tocar la otra pieza y moverla un poco, o deshacer el último cambio con la flecha.']],
    extra: ["Escriure una cartel·la per a l'escultura: títol, autor/a, formes i vista preferida.|Escribir una cartela para la escultura: título, autor/a, formas y vista preferida.", "Buscar escultures reals de l'entorn (a la plaça, al parc) i dir de quines formes estan fetes.|Buscar esculturas reales del entorno (en la plaza, en el parque) y decir de qué formas están hechas.", 'Fer una segona versió de l\'escultura amb el suggeriment del company.|Hacer una segunda versión de la escultura con la sugerencia del compañero.'],
    trans: ['Unitat següent: les formes bàsiques (caixes, cilindres, cons, esferes i piràmides) i les seves mides.|Unidad siguiente: las formas básicas (cajas, cilindros, conos, esferas y pirámides) y sus medidas.', 'Educació artística: el volum i l\'escultura.|Educación artística: el volumen y la escultura.'],
    slides: [
      { id: 's1', k: 'portada', t: 'La meva primera escultura|Mi primera escultura', x: "Projecte: l'exposició del taller|Proyecto: la exposición del taller", nota: "Explica el projecte: una escultura de 3 a 5 formes per a l'aparador de la biblioteca.|Explica el proyecto: una escultura de 3 a 5 formas para el escaparate de la biblioteca." },
      { id: 's2', k: 'pregunta', t: 'Què té una escultura que no té un dibuix?|¿Qué tiene una escultura que no tiene un dibujo?', x: 'Pensa en les estàtues de la plaça o del parc.|Piensa en las estatuas de la plaza o del parque.', nota: 'Busquem: es pot mirar per tots els costats, té volum, fa ombra.|Buscamos: se puede mirar por todos los lados, tiene volumen, hace sombra.' },
      { id: 's3', k: 'media', t: "L'escultura d'exemple|La escultura de ejemplo", x: 'Peu, columna, bola i estrella: 4 formes.|Pie, columna, bola y estrella: 4 formas.', media: { k: 'model', model: { parts: ESCULT } }, nota: "Gira-la i atura't a la vista on l'estrella gairebé desapareix (el costat).|Gírala y detente en la vista donde la estrella casi desaparece (el lado)." },
      { id: 's4', k: 'anim', t: 'Equilibri|Equilibrio', anim: 'm14balance', x: 'Gran a baix, petit a dalt.|Grande abajo, pequeño arriba.', nota: 'Connecta amb la impressora: una base ampla s\'enganxa millor a la placa.|Conecta con la impresora: una base ancha se pega mejor a la placa.' },
      { id: 's5', k: 'media', t: 'Contrast|Contraste', x: 'Rodó i punxegut, alt i baix, colors que fan parella.|Redondo y puntiagudo, alto y bajo, colores que hacen pareja.', media: { k: 'model', model: { parts: CONTRAST } }, nota: 'Demana quines parelles de contrast hi veuen.|Pide qué parejas de contraste ven.' },
      { id: 's6', k: 'anim', t: 'El procés de disseny|El proceso de diseño', anim: 'm14steps', x: 'Idea, esbós, model i revisió.|Idea, boceto, modelo y revisión.', nota: "Avui farem els quatre passos. La fletxa de tornada vol dir que es pot millorar.|Hoy haremos los cuatro pasos. La flecha de vuelta quiere decir que se puede mejorar." },
      { id: 's7', k: 'concepte', t: 'La norma de la Nuvi|La norma de Nuvi', x: 'Cada peça ha de tocar la placa o una altra peça. Res no pot flotar.|Cada pieza tiene que tocar la placa u otra pieza. Nada puede flotar.', nota: 'Recorda la z de la sessió anterior: la peça de dalt comença on acaba la de sota.|Recuerda la z de la sesión anterior: la pieza de arriba empieza donde acaba la de debajo.' },
      { id: 's8', k: 'activitat', t: "L'esbós|El boceto", timer: 10, punts: ['Pensa una idea.|Piensa una idea.', 'Dibuixa-la de davant a la quadrícula.|Dibújala de delante en la cuadrícula.', 'Escriu la llista de formes i colors.|Escribe la lista de formas y colores.', 'Ensenya-la al company.|Enséñasela al compañero.'], nota: 'Als cinc minuts, intercanvi amb el company del costat.|A los cinco minutos, intercambio con el compañero de al lado.' },
      { id: 's9', k: 'repte', t: "A l'ordinador: l'entrenament|En el ordenador: el entrenamiento", punts: ['Troba i arregla la bola que flota.|Encuentra y arregla la bola que flota.', 'Fes el tòtem de tres pisos.|Haz el tótem de tres pisos.', "Construeix l'arc.|Construye el arco."], nota: 'Són reptes curts: l\'objectiu és practicar la z abans de l\'escultura.|Son retos cortos: el objetivo es practicar la z antes de la escultura.' },
      { id: 's10', k: 'media', t: 'Troba la peça que flota|Encuentra la pieza que flota', x: "Gira l'escultura: on hi ha aire?|Gira la escultura: ¿dónde hay aire?", media: { k: 'model', model: { parts: FLOTA }, view: 'front', spin: false }, nota: 'Entre la bola i la columna hi ha 4 mm d\'aire. Es veu millor de davant.|Entre la bola y la columna hay 4 mm de aire. Se ve mejor de delante.' },
      { id: 's11', k: 'media', t: "L'arc|El arco", x: 'Columnes a x = −20 i x = 20; la biga a z = 20.|Columnas en x = −20 y x = 20; la viga en z = 20.', media: { k: 'model', model: { parts: ARC }, view: 'front', spin: false }, nota: "Fes-ho a la pissarra per a qui s'encalli. Una escultura també pot tenir forats!|Hazlo en la pizarra para quien se atasque. ¡Una escultura también puede tener huecos!" },
      { id: 's12', k: 'repte', t: 'La teva escultura|Tu escultura', punts: ['De 3 a 5 formes.|De 3 a 5 formas.', 'Toca la placa i res no flota.|Toca la placa y nada flota.', 'Almenys 2 colors.|Al menos 2 colores.', 'Bonica de totes les vistes.|Bonita desde todas las vistas.'], nota: 'Les comprovacions es marquen soles. Quan estan totes, es pot desar.|Las comprobaciones se marcan solas. Cuando están todas, se puede guardar.' },
      { id: 's13', k: 'concepte', t: "Crítics d'art|Críticos de arte", x: "Mira l'escultura del company: digues una cosa que t'agrada i una idea per millorar-la.|Mira la escultura del compañero: di una cosa que te gusta y una idea para mejorarla.", nota: "Model de frase: «M'agrada… Potser podries…». Sempre amb respecte.|Modelo de frase: «Me gusta… Quizá podrías…». Siempre con respeto." },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Una escultura es dissenya pensant en totes les vistes.|Una escultura se diseña pensando en todas las vistas.', 'El procés: idea, esbós, model i revisió.|El proceso: idea, boceto, modelo y revisión.', 'Per imprimir, res no pot flotar.|Para imprimir, nada puede flotar.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Digues un pas del procés de disseny.|Di un paso del proceso de diseño.', 'Per què una peça no pot flotar?|¿Por qué una pieza no puede flotar?'], nota: 'Oral, durant la galeria: cada autor/a respon una pregunta.|Oral, durante la galería: cada autor/a responde una pregunta.' },
      { id: 's16', k: 'concepte', t: 'A casa|En casa', x: "Ensenya l'escultura a algú de casa i explica-li com l'has feta.|Enseña la escultura a alguien de casa y explícale cómo la has hecho.", nota: 'Proposta opcional. Si s\'imprimeix alguna escultura, es pot exposar la setmana següent.|Propuesta opcional. Si se imprime alguna escultura, se puede exponer la semana siguiente.' }
    ],
    print: [
      { id: 'p1', t: "Esbós de l'escultura|Boceto de la escultura", k: 'graella', w: 10, h: 10, intro: "Dibuixa la teva escultura vista de davant. Cada quadret fa 10 mm: la placa del dibuix fa 100 × 100 mm.|Dibuja tu escultura vista de delante. Cada cuadrito mide 10 mm: la placa del dibujo mide 100 × 100 mm.",
        legend: [['1', 'La forma de baix de tot (la base)|La forma de abajo del todo (la base)'], ['2', 'La forma que hi ha a sobre|La forma que hay encima'], ['3', 'I així fins a 5 formes|Y así hasta 5 formas']],
        items: [{ q: 'Llista de formes (forma, color i on va):|Lista de formas (forma, color y dónde va):', big: true }, { q: "Títol de l'escultura:|Título de la escultura:" }] },
      { id: 'p2', t: "Fitxa del crític/a d'art|Ficha del crítico/a de arte", k: 'fitxa', intro: "Mira l'escultura d'un company a l'ordinador, gira-la i respon. Recorda: sempre amb respecte.|Mira la escultura de un compañero en el ordenador, gírala y responde. Recuerda: siempre con respeto.",
        items: [{ q: "Com es diu l'escultura i qui l'ha feta?|¿Cómo se llama la escultura y quién la ha hecho?", sol: 'Resposta oberta.|Respuesta abierta.' }, { q: 'Quantes formes té? Quines?|¿Cuántas formas tiene? ¿Cuáles?', sol: 'Entre 3 i 5 formes.|Entre 3 y 5 formas.' },
          { q: 'Hi ha alguna peça que floti? Com ho has comprovat?|¿Hay alguna pieza que flote? ¿Cómo lo has comprobado?', sol: "No n'hi hauria d'haver: s'ha de mirar des de davant i des del costat.|No debería haber ninguna: hay que mirar desde delante y desde el lado." },
          { q: "Una cosa que m'agrada i una idea per millorar-la:|Una cosa que me gusta y una idea para mejorarla:", sol: 'Resposta oberta, respectuosa i concreta.|Respuesta abierta, respetuosa y concreta.', big: true }] }
    ]
  },
  };
})());
